INSERT INTO `w_bo_gd_20250707155940` VALUES ('2057035914638483458', '0', '0', '17253690046572896', '周宇', '2026-05-20 17:49:15', '17201757871959617', '赵倩', '2026-07-16 17:02:49', '1', '2057035914869112834', 'RUNNING', '运行中', '909783222', '评香部', '15', 'YPGD-20260520-0033', '2056291853073866754', '昆山永青--食品级香精推荐20260518', NULL, '1', '需求明确', '1', '客户新品开发', '206', '口腔护理', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '113845370124130976,16466317325076496', NULL, '2034161062508478465', '刘柳', '刘柳\n15962636827\n昆山市千灯镇石浦声荣路188号\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'DHR1288ADH 闪点改到合规（65左右），气味不变下进行调整\n需求时间：7.16 需求紧急，20g香精寄出\n法规后续查验\n-------------------------------之前信息 -----------------------\nSTEP 1 -- 本次推荐样品，已请翟工进行 “美国+欧洲+81过敏原” 法规核验，烦请客户先确认香气；本轮选中后，再进行 HALA 配方调整，法规核验、香气再确认，及HALA认证等；', NULL, 'SF5117448482895', NULL, 'false', NULL, '彭佳庆,梁皓', '推荐现有库存的食品级香精\n需要美食调和果香调，推荐8~10款\n需要符合Hahla认证、美国加州法案关于唇部用品法规以及欧盟法规\n81过敏原\n产品用于唇部\n需要调整请联系调香师\n需求价格：300以内\n需求时间：5.29需寄出\n\n备注：\n-配方需优先符合Halal认证条件、美国加州法案关于唇部用法规部分、欧盟出口需求，\n-Halal可后续客户确认香型后在进行认证\n\n-无库存可联系调香师修改符合需求样品', '昆山永青--食品级香精推荐20260518', NULL, NULL, NULL, NULL, NULL);
