INSERT INTO `w_bo_gd_20250707155940` VALUES ('2057686249853902849', '0', '0', '16455177663846080', '常晓爽', '2026-05-22 12:53:27', '17201757871959617', '赵倩', '2026-06-08 16:37:29', '1', '2057686250252304386', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260522-0024', '2057012509742686209', '欧菲丽生物-单一花香系列-20260520', NULL, '1', '需求明确', '1', '客户新品开发', '207', '其他个人护理', '2027-05-20 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '适应区150-200元之间', '17400514601408872,05035817437137', NULL, '2057014658904055809', '晁工', '晁工\n13363950390\n陕西省西安市浐灞生态区咸宁东路24号长安时间.西安灯泡厂\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0228498279683', NULL, 'false', NULL, '于姗姗,宣二鹏', '请按照香型需求，研发食品级香精，每个香型两款\n单一花香：\n①茉莉\n香调组合：小花茉莉净油 + 大花茉莉浸膏 + 银针白茶 + 西瓜酮\n②樱花\n香调组合：日本樱花香基 + 粉红胡椒 + 紫苏叶 + 降龙涎香醚\n③栀子\n香调组合：栀子花浸膏 + 依兰依兰 + 可可壳 + 檀木\n④青梅\n香调组合：青梅萃取 + 日本柚子 + 薄荷 + 柏木\n用途：成人用品润滑油\n标签上写上：项目：单一花香系列', '欧菲丽单一花香', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2057687297448435713', '0', '0', '16455177663846080', '常晓爽', '2026-05-22 12:57:36', '17201757871959617', '赵倩', '2026-06-08 16:41:27', '1', '2057687297653899265', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260522-0025', '2057013288415223810', '欧菲丽生物-推荐花香+果香-20260520', NULL, '1', '需求明确', '1', '客户新品开发', '207', '其他个人护理', '2027-05-20 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150-200', '17400514601408872,05035817437137', NULL, '2057014658904055809', '晁工', '晁工\n13363950390\n陕西省西安市浐灞生态区咸宁东路24号长安时间.西安灯泡厂\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0228498279683', NULL, 'false', NULL, '于姗姗,宣二鹏', '请按照如下信息，研发复配食品级香精，每个香型两款\n花香+果香：\n①青梅+樱花+黑醋栗\n②栀子花+无花果+青梨\n③茉莉+蜜桔+桃\n④樱花+覆盆子+荔枝\n⑤青梅+黑加仑+佛手柑\n\n花香+木香：\n①栀子花+檀木+柏木\n②樱花+日本扁柏+降龙涎香醚\n③茉莉+雪松+愈创木\n④青梅+桧木+岩兰草\n⑤桂花（辅助）+雪松+广藿香\n\n花香+果香+木香：\n①茉莉+蜜桔+柏木+零陵香豆\n②栀子花+无花果叶+檀木+橡木苔\n③樱花+覆盆子+日本扁柏+白麝香\n④樱花+覆盆子+日本扁柏+白麝香\n⑤茉莉+日本柚子+檀木+焚香\n食品级别，香精各10克，每个项目做两款香精，标签上写上：项目：花香+果香', '欧菲丽 花香+果香', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2057704080737787906', '0', '0', '16825006662777257', '齐钰', '2026-05-22 14:04:18', '17201757871959617', '赵倩', '2026-06-01 15:35:31', '1', '2057704081266212865', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260522-0026', '2056920311051280386', '船王-推荐香精乌木玫瑰和温木玫瑰-20260520', NULL, '1', '需求明确', '3', '双马香精升级', '202', '身体清洁', '2027-05-20 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '130-140以内的', '17400514601408872,05035817437137', NULL, '2056631105192157186', '开心', '开心\n17824244552\n浙江省杭州市萧山区宁围街道望京C2座802\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'true', NULL, '于姗姗,宣二鹏', '【LJF2083ALJ 檀香玫瑰】不变色 50g\n要求：上次乌木玫瑰香精，没有选中，你这边还有合适的推荐吗 另外 温木玫瑰 变色严重，然后我们这边安排皂粒寄过去，预计明天寄出，直接用我们的皂粒打皂寄过来给我们，添香量一般1.2%，但是上次那个温木玫瑰比较淡，我们加到了1.5%。您看看推荐的那几个香精如果也是一样比较淡的话，添加到1.5%试试\n用途：香皂用，不变色，香精50克\n地址收件人; 开心', '【檀香玫瑰 LJF2083ALJ】修改', NULL, NULL, NULL, NULL, NULL);
