INSERT INTO `w_bo_gd_20250707155940` VALUES ('2061347412558962690', '0', '0', '05035817329389', '刘畅', '2026-06-01 15:21:36', '113845370124130976', '彭佳庆', '2026-06-29 16:25:55', '1', '2061347412785397761', 'RUNNING', '运行中', '12377314', 'DHFF', '13', 'YPGD-20260601-0055', '2061337368832466945', 'Deepmoss--厦门风谷--香水创香20260601', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓,王晔', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '500-800', '113845370124130976,16466317325076496,17127345845433575', NULL, '2061336488909430785', '夏雪莲', '夏雪莲\n19946037315\n中国（福建）自由贸易试验区厦门片区高崎南五路222号航空商务广场3号楼第3层5楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '【更新】Deepmoss创香需求\n以  阿特拉斯雪松 为主 副料为乳香、麝香龙涎\n做3个不同方向的创香\n客户选中主题有：芫荽、四川青花椒、榄香、橙叶、灵猫酮\n需要有暖感的木质香型，只需要考虑香气高级感无需考虑市场接受度\n该产品为客户vip赠送高定款\n-\n价格：1000以内\n需要15% & 20%香水加香产品\n时间：6.26', 'LYP2443ALY-探索1-黄 LYP2444ALY-探索2-绿 LYP2445ALY-探索3-棕', '74100603680990', '2026-06-29 00:00:00', NULL, NULL, '彭佳庆,梁皓,王晔', '项目需求：Deepmoss是一家国内高端服装设计师品牌，计划推出品牌signature香水，彰显deepmoss品牌的美学和价值。\n\n报价及项目类型：香水香精预算500-800人民币/公斤。要求调香师0-1创香，并希望后续能与调香师展开创作沟通。\n\n目前阶段需求：要求寄送6位调香师的创香作品，根据风格选择后续合作调香师。选定调香师后会发送具体的香水概念及香调brief需求。\n\n调香师作品寄出时间：本周ASAP\n\n香精定版及出货时间：6月底', 'Deepmoss厦门风谷第一批递样-调香师选定', '1', '无', NULL, NULL, NULL);
