INSERT INTO `w_bo_gd_20250707155940` VALUES ('2061726600734400514', '0', '0', '17253690046572896', '周宇', '2026-06-02 16:28:21', '17201757871959617', '赵倩', '2026-06-18 15:45:23', '1', '2061726601036333058', 'RUNNING', '运行中', '909783222', '评香部', '7', 'YPGD-20260602-0056', '2057029494580928514', '山下有松--陈皮青柑藤条修改20260520', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400以内', '113845370124130976,16466317325076496', NULL, '2048619010949341186', '王妍', '王妍\n13581841518\n北京市朝阳区浩华文创园C9songmont 王妍 13581841518\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '优先测试 -- JKA2209MJK 藤条版，做蜡烛的冷香+热香效果；\n若效果可以，则直接寄 蜡烛加香样；\n若效果一般，烦请修改调整后 寄样，谢谢！\n\n06/16 日志 -- 客户急需样品，暂不用测试点燃效果，直接寄加香样；', NULL, 'SF5134678690791', NULL, NULL, NULL, '彭佳庆,梁皓', '北京市朝阳区浩华文创园C9songmont 王妍 13581841518\n-\n项目号：XMBM202605200024\n新需求：客户需要<陈皮青柑>蜡烛版，以	JKA2209MJK 藤条版为基础修改，香气格蓬＋陈皮为主；\n需要测试燃烧时的香气表现，加香量12%\n需额外注意闪点问题\n-\n需求价格400以内\n寄样时需要加香产品12%\n需求时间：6.12', '山下有松--陈皮青柑蜡烛修改_20260602', '2', '加香', NULL, NULL, NULL);
