INSERT INTO `w_bo_gd_20250707155940` VALUES ('2062734818084335617', '0', '0', '16455177663846080', '常晓爽', '2026-06-05 11:14:39', '17201757871959617', '赵倩', '2026-06-09 18:02:29', '1', '2062734818289807362', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260605-0030', '2062712627808645121', '戈海  DH-A33845--JKB2490AJK 香格里拉 优化调整', NULL, '1', '需求明确', '2', '客户老品升级', '202', '身体清洁', '2027-06-06 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '120元左右', '1638968357988946', NULL, '2034161061858361346', '居居', '居居\n13922118445\n广州市天河区珠江新城华夏路富力盈通2810室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0226528415600', NULL, NULL, NULL, '何家文', '根据以下信息，调整优化\n型号：DH-A33845--JKB2490AJK 香格里拉\n背景：DH-A33845--JKB2490AJK这款香精现客户用于洗护沐和喷雾产品，但测试下来有两个产品不是很好理想\n需求一：客户沐浴露，沐浴露的基体是表活，添加量1.2%，要出口到中东市场。反馈产品香气还是淡，需要帮忙继续加强香气。\n需求二：喷雾产品 添加香精后，后调出现发酸的情况，麻烦按照客户配方帮忙再优化一下。\n喷雾的配方：水、PEG-40氢化蓖麻油、甘油、香精、苯氧乙醇、羟苯甲酯、乙基己基甘油、乙二胺四乙酸二钠、丁二醇、甲基二异丙基丙酰胺、聚山梨酯20', '戈海香格里拉优化', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2062736016065638401', '0', '0', '16455177663846080', '常晓爽', '2026-06-05 11:19:25', '17201757871959617', '赵倩', '2026-06-10 17:17:45', '1', '2062736016380162049', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260605-0032', '2062371602770649089', '仙迪刷酸清爽沐浴慕斯', NULL, '1', '需求明确', '1', '客户新品开发', '202', '身体清洁', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '待确认', '1638968357988946', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '何家文', 'HDB2293EHD，加一些后段留香的原料，有一定的潮湿感，可以家乌梅香基\n沐浴慕斯，然后主打一个刷酸刷酶，然后去掉身上鸡皮的这个概念。然后希望在夏天比较热的时候去主推，所以这个味道要相对比较清新比较清爽，然后有一点带酸味，然后有一种雨后的这种苔藓的这种留香\n清爽、自然、舒适\n1）普宁的青梅-酸酸的雨后苔藓\n2）牛油果\n3）其他方向杨桃、白葡萄酒', '仙迪沐浴啫喱', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2062738468022202370', '0', '0', '16275212368889684', '赵文雅', '2026-06-05 11:29:09', '17201757871959617', '赵倩', '2026-06-18 15:47:47', '1', '2062738468194119682', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260605-0035', '2057311598682267650', '山东名联香精推荐26-05-21', NULL, '1', '需求明确', '5', '香精库推荐', '401', '宠物护理', '2027-05-21 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '02461210300720808373', NULL, '2057308131741884417', '孙宗军', '孙宗军\n18396716868\n山东省临沂市费县胡阳镇北尹村工业园8号山东名联生物科技有限公司\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0224969376037', NULL, NULL, NULL, '余鹏程', '1、请安排“茉莉”和“柠檬”味的香型，油质、水质（用于宠物除臭剂，需无色）和粉末（用于宠物洗护产品，类似爆炸盐）都需要，每个类型尽量各安排3款，液体香精价位100~150以内，粉末60~80左右；\n2、请推荐爆款洗护香型3~5款，用于宠物玩具清洗液，需油质，价位150以内\n3、爆款喷雾香型5款，用于宠物喷雾，需水质，不要有颜色，价位100左右\n4、爆款爆炸盐香型5款，用于宠物洗护产品，价位80左右\n*标签请注明“产品名称、油质/水质”', '推荐', '2', '加香', NULL, NULL, NULL);
