INSERT INTO `w_bo_gd_20250707155940` VALUES ('2062752101296975873', '0', '0', '16455177663846080', '常晓爽', '2026-06-05 12:23:20', '17201757871959617', '赵倩', '2026-06-16 16:24:33', '1', '2062752101582139394', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260605-0038', '2062087104774496258', '江苏大熊织物洗护香精推荐26-06-03', NULL, '1', '需求明确', '5', '香精库推荐', '101', '传统织物洗护', '2027-06-03 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '140', '02461210300720808373', NULL, '2062081617911832578', '张伟', '张伟\n13921369661\n江苏省盐城市建湖县冠华路东方康城北门大熊散装洗化\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5134087247896', NULL, NULL, NULL, '余鹏程', '1、请推荐玫瑰香型3款，要求留香好（比如格拉斯玫瑰、乌木玫瑰），用于洗衣液，价位140以内\n2、青提茉莉  薰衣草 各1~2款，要求留香好，用于洗衣液，价位140以内\n3、松木香型1款，用于皂液，价位120以内\n4、市面流行低端洗衣液爆款香型3~5款，价位140以内\n5、栀子花水性香精1~2款，用于地板清洗剂，价位100左右', '江苏大熊织物洗护香精推荐', '2', '加香', NULL, NULL, NULL);
