INSERT INTO `w_bo_gd_20250707155940` VALUES ('2062752663086247938', '0', '0', '16275212368889684', '赵文雅', '2026-06-05 12:25:34', '17201757871959617', '赵倩', '2026-06-16 14:26:46', '1', '2062752663291719682', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260605-0041', '2062451418702241793', '聆听四季-推荐和指定香精-20260604', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-06-04 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '0549274114954944,17400514601408872', NULL, '2062450580659331074', '刘', '刘\n15736715345\n广州市番禺区博域大厦705\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0220839141880', NULL, NULL, NULL, '王鑫,于姗姗', '要哪些香型。我们目前规划了两个产品线，香包及枕香，目前初步确定了想要的香味，具体香型需求如下：\n1. 杨桃清梦\n2. 甜瓜与白茉莉\n3. 冬季乌木\n4. 椰青与石榴\n5. 绿藤香根\n6. 琥珀繁花\n7. 苍苔柏木\n8. 忍冬铃兰\n9. 青苹果\n10. 蔷薇秘语\n还有附件的香精\n各15克\n用于空间香氛', '香链广州', '1', '无', NULL, NULL, NULL);
