INSERT INTO `w_bo_gd_20250707155940` VALUES ('2063915017916329986', '0', '0', '17253690046572896', '周宇', '2026-06-08 17:24:21', '113845370124130976', '彭佳庆', '2026-06-29 10:52:57', '1', '2063915018172125185', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260608-0039', '2063824042019729410', '其里--山苍子、裸男创香、修改20260608', NULL, '1', '需求明确', '1', '客户新品开发', '202', '身体清洁', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '洗护个护220以内 & 蜡烛350以内', '16466317325076496,113845370124130976', NULL, '2034161060243554306', 'Lancelot', 'Lancelot\n15618191227\n上海市徐汇区龙华中路600号绿地中心B座1102室 Lancelot，15618191227\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '山苍籽需要 精油感，蜡烛价格较高；', 'LYC2437ALY-山苍子1（蜡烛）LYB2437BLY-山苍子2（个护）LYB1074CLY-航迹1（个护）', '74100603680986', '2026-06-26 00:00:00', NULL, NULL, '梁皓,彭佳庆', '上海市徐汇区龙华中路600号绿地中心B座1102室 Lancelot，15618191227\n根据客户需求进行修改、创香\n需求1：山苍子创香（蜡烛、洗护、手霜）\n根据客户线下感受山苍子的香气\n需要一款类似精油感的蜡烛版以及护手霜和洗护版\n蜡烛版需求价格：350以内，需要一个蜡烛10%加香产品\n洗护、手霜版需求价格220以内\n该款需注意闪点问题！！！！！！！！！！\n\n需求2：裸男修改（洗护、手霜）\nLYP1074ALY 客户喜欢原版香水其中后调的麝香粉香部分，可略微保留部分海洋水生\n产品用于洗护个护产品内\n需求价格220以内\n该版本需要一个好听的名称\n\n只有蜡烛版需要10%加香产品其余寄样香精即可\n需求时间：6.18', '其里--山苍籽、裸男修改_20260608', '1', '无', NULL, NULL, NULL);
