INSERT INTO `w_bo_gd_20250707155940` VALUES ('2064259668280029186', '0', '0', '16275212368889684', '赵文雅', '2026-06-09 16:13:52', '17201757871959617', '赵倩', '2026-06-10 18:42:01', '1', '2064259668498075649', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260609-0043', '2062833505443721217', '浙江嘉柯香精推荐26-06-05', NULL, '1', '需求明确', '5', '香精库推荐', '502', '其他', '2027-06-05 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400', '02461210300720808373', NULL, '2062833719118344193', '柳倩倩', '柳倩倩\n18868318975\n浙江省丽水市莲都区绿源路 9-1号\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '余鹏程', '请推荐2款白茶、2款苹果，后期用于微胶囊，给树脂类加香\n要求香气强度大，价格400内\n【快递寄给许倩倩】', '推荐', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2064261717172367362', '0', '0', '16825006662777257', '齐钰', '2026-06-09 16:22:00', '17201757871959617', '赵倩', '2026-06-16 16:10:24', '1', '2064261717415579649', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260609-0045', '2064187869647286273', '香水博主方生  2款新品香水', NULL, '1', '需求明确', '5', '香精库推荐', '301', '个人香氛', '2027-06-12 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000元以内', '1638968357988946', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5197065774805', NULL, NULL, NULL, '何家文', '这两款香水需要搭配PPT一起带过去给客户做介绍.    香精30g，做加香20%\n产品：香水\n价格：2000元以内\n产品一名字：抽离\n核心概念与意境：\n精准诠释粤语「撇」的内核：潇洒离场、瞬间抽离、抛开杂念、事过翻篇、利落不纠缠，不带有攻击性与烦躁感，主打清凉醒神、情绪舒缓、内心安定的状态，是从繁杂琐事中抽身，一身轻的松弛利落感，做到凉而不冲、稳而不沉、收尾干净。\n目标受众：\n追求极简生活、情绪内敛、需要快速平复心绪、偏爱清冷木质草本香的男女群体，适配通勤、社交、独处等多场景，拒绝甜腻、厚重、刺鼻香感。\n整体香调：清冷草本木质调\n核心气味特征：清凉通透、舒缓镇定、沉稳安定、利落无拖沓\n参考框架：\n前调:薄荷，香柠檬，柚子，山苍子\n中调:薰衣草，迷迭香，雪松，广藿香\n后调:香根草，檀香，乳香\n\n产品二名字：放空\n包装设计元素：Hea\n核心概念与意境（重中之重）精准诠释粤语「hea」的核心内涵 ——不费力的慵懒、慢悠悠的松弛、不慌不忙的惬意，无颓废感，主打 “摇椅上晒阳光、闭眼小憩” 的治愈感，气味核心是「暖融融的阳光感 + 软糯慵懒感」，传递 “什么都不想做、只想安心 hea 着” 的松弛情绪，贴合老广慢生活的松弛态度。\n目标受众：偏爱温柔贴肤香、追求松弛感生活、喜爱岭南文化的年轻群体，男女通用，适配居家、独处、通勤等低社交场景，拒绝刺鼻、厚重、甜腻、提神的香感。\n整体香调：暖柔阳光木质花香调（偏糯感、贴肤）\n核心气味特征：阳光暖润、软糯慵懒、舒缓治愈、低扩散贴肤，无攻击性、无尖锐感，全程暖而不燥、柔而不腻、慢而不沉。\n参考框架：\n前调:向日葵 青柠 阳光 佛手柑\n中调:白兰 姜花 椰子 鸡蛋花 白檀 \n后调:零陵香豆 愈创木 香根草 麝香\n\n可以参考客户提供的香型框架进行调香。\n时间：6月24号前寄出到广州就可以\n一套香精30克+加香样品（添加量：20%）\n\n地址：广州市越秀区中山六路越秀新都会5楼WeWork 05-122房\n何家文 18620840308', '【产品1：抽离】', '2', '加香', NULL, NULL, NULL);
