INSERT INTO `w_bo_gd_20250707155940` VALUES ('2064527307535536130', '0', '0', '17253690046572896', '周宇', '2026-06-10 09:57:22', '113845370124130976', '彭佳庆', '2026-08-11 15:22:41', '1', '2064527307812356098', 'RUNNING', '运行中', '909783222', '评香部', '14', 'YPGD-20260610-0005', '2064276232815456258', 'Wildsniff--香樟树香水修改20260609', NULL, '2', '样品确认', '1', '客户新品开发', '301', '个人香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '1000左右', '113845370124130976,16466317325076496', NULL, '2062484697853681665', '朱小姐', '朱小姐\n13602818974\n宁波市海曙区段塘街道万科海潮映月小区西区14幢21单元105室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP2054QLY >>> 大众化方向调整\n需要15%香水加香产品，7.29', 'LYP2054OLY-香樟树5\n\nLYP2054ULY-香樟树7（香水）', '74100603681641/74100603681648', '2026-08-11 00:00:00', NULL, NULL, '彭佳庆,梁皓', 'LYP2054LLY 香樟树\n应客户需求做清透水感芳香清甜感修改\n产品用于香水\n需求价格：1000左右\n需要15%香水加香\n时间：06/18', 'Wildsniff--香樟树香水修改20260609', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2064529469908963330', '0', '0', '17253690046572896', '周宇', '2026-06-10 10:05:57', '113845370124130976', '彭佳庆', '2026-08-11 14:12:39', '1', '2064529470227726338', 'RUNNING', '运行中', '909783222', '评香部', '31', 'YPGD-20260610-0006', '2064271067555246082', '荒核--蜂蜜橙花、油柑樟木、薄荷创香20260609', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"核荒-橙花.xlsx\",\"timestamp\":\"SLgXiRiiYCvkuUADMVOo\",\"size\":16778,\"secret\":null,\"fileId\":\"8bef5d90-364a-4cfa-816b-472f957148e4\",\"showSize\":\"16KB\",\"fileClass\":\"iconBox excelBox\"}]', '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '1000~1500', '113845370124130976,16466317325076496', NULL, '2080187936426397697', '李小姐（徐泾）', '李小姐（徐泾）\n15000707254\n上海上海市青浦区徐泾镇 详细地址: 联涞路138弄虹悦湾6-17-202 李小姐 15000707254\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP2054SLY客户反馈林中野果优化方向正确，希望最后再减少1/4果甜感；\n需要20%香水加香产品', 'LYP2054PLY-林中野果1 LYP2054RLY--林中野果2 LYP2452ALY-醋栗欧蓍草1\n\nLYP2054SLY-林中野果3   LYP1417FLY-薄荷花3\n\nLYP2054TLY-林中野果4（香水）', '出外部号', '2026-08-11 00:00:00', NULL, NULL, '彭佳庆,梁皓', '无需寄样，创香完成后客户自取\n根据客户现在讨论确定26年度香水创香\n需求1：野花香水创香  目前客户在品牌转型阶段，自然与人的链接会对目前已有产品进行迭代升级\n客户已有橙花产品做仿香升级，在仿香基础上增加蜂蜜元素\n\n需求2：野果香水  LYP2054LLY+松针蒎烯的涩感+轻微的苹果/黄皮果香\n\n需求3：LYP2266ALY  薄荷由评香/调香确定往果香调整还是花香调整\n产品均用于香水内\n需要20%香水加香产品\n需求价格：1000~1500\n需求时间：6.26', '荒核--蜂蜜橙花、油柑樟木、薄荷创香20260609', '1', '无', NULL, NULL, NULL);
