INSERT INTO `w_bo_gd_20250707155940` VALUES ('2064621903460421633', '0', '0', '16455177663846080', '常晓爽', '2026-06-10 16:13:15', '16455177663846080', '常晓爽', '2026-07-03 13:48:35', '1', '2064621903691104258', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260610-0044', '2064181720092979202', '广州仙迪   独特艾琳洗护仿香项目', NULL, '1', '需求明确', '1', '客户新品开发', '202', '身体清洁', '2027-06-06 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"炽热记忆-白盖.xlsx\",\"timestamp\":\"RlJ1fmhz34cIKZ3Rb40Q\",\"size\":19825,\"secret\":null,\"fileId\":\"a80acad3-6b8f-47bd-b661-0dc499ecfd92\",\"showSize\":\"19KB\",\"fileClass\":\"iconBox excelBox\"}]', '何家文,王鑫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '无', '1638968357988946,0549274114954944', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '不寄样', NULL, NULL, NULL, NULL, NULL, '何家文,王鑫', '独特艾琳仿香项目37款、\n艾克斯假期、塞班假日、耳畔铃兰、鎏金之梦、浮靡之光、炽热记忆、雨后桃金娘、游子吟、杜乐丽花园、孜瑰诗集、清澈泉涌、清澈岛屿、你最珍桂、我的少年、苏里南柠、宇宙星辰、漫步初春、北岛流光、春日旷野、光影倾城、清茶琥珀、浮靡之水、灌璨流星、琥珀之钥、空山雪茶、心跳回响、大地森林、繁华花园、橡木苔的夏、欲望宇宙、日落少女、加州柚里、布列塔尼、仲夏和歌山、莱茵河白昼、雨季绿地、纯净之檀\n要求：仙迪未来重点推广的项目，要求相似必须高，价格尽可能控制，不要太高。\n时间：客户希望月底能完成一部分，麻烦安排加急一下。', '炽橙记忆', '1', '无', NULL, NULL, NULL);
