INSERT INTO `w_bo_gd_20250707155940` VALUES ('2064892635444662274', '0', '0', '17253690046572896', '周宇', '2026-06-11 10:09:03', '050363634136321790', '逯柏松', '2026-07-17 15:21:10', '1', '2064892635687927809', 'SUCCESS_END', '成功结束', '909783222', '评香部', '9', 'YPGD-20260611-0007', '2064612759651209218', '深林雪松（创香）-西苔', NULL, '6', '输单', '1', '客户新品开发', '302', '空间香氛', '2026-06-18 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300', '113845370124130976,050363634136321790', NULL, '2059907565130571778', 'Bella', 'Bella\n15257009611\n浙江省杭州市萧山区盈丰街道永晖路233号杭州湾智慧谷10楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '参照项目说明', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '无火、蜡烛、水性香 需要加香产品各一个；不用寄香精样\n标样已寄，需要应用加香 烦请打样 50g，谢谢！\n\n【加香需求】\n> 无火10%-异构溶剂90%香精10%（客供base）\n> 蜡烛5%-蜡烛基料95%香精5%（客供base）\n> 水性喷雾3%-去离子水73% 酒精15%SEI 9% 香精3%（先香精和SEI融合好，再加水和酒精）', 'LYB2446ALY-木林森1 LYC1682FLY-木林森2 LYC1552ILY-木林森3', 'SF5113715151755', NULL, NULL, NULL, '彭佳庆,逯柏松', 'LYP1552BLY\nLYP1204ALY\nLYP1682BLY\nLYP964ALY\nLYP586CLY\n\n需要修改成适合无火，蜡烛，喷雾的香型，并且需要添加白皮松精油（有希），5选3个配方进行修改（自行把控），整体方向就是森林，植物，木，可自行发挥\n价格：300以内\n应用：无火10%；蜡烛5%；水性喷雾3%\n香精：各15ml\n备注：其中无火和蜡烛需要通用品类版本ACM；水性喷雾需要透明水质版\n都需要加香产品各一个\n时间：6月18号前寄出\n\n邮寄地址：\n浙江省杭州市萧山区盈丰街道永晖路233号杭州湾智慧谷10楼\nBella\n15257009611\n\n\n邮寄地址：\n浙江省杭州市萧山区盈丰街道永晖路233号杭州湾智慧谷10楼\nBella\n15257009611', '深林雪松（创香)--西苔20260611', '2', '加香', NULL, NULL, NULL);
