INSERT INTO `w_bo_gd_20250707155940` VALUES ('2064905211440254977', '0', '0', '17253690046572896', '周宇', '2026-06-11 10:59:01', '113845370124130976', '彭佳庆', '2026-06-23 13:59:11', '1', '2064905211670937602', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260611-0016', '2064889277090615297', '忍冬复方精油仿香-逐本', NULL, '1', '需求明确', '1', '客户新品开发', '201', '头发洗护', '2026-09-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"忍冬复方精油.xlsx\",\"timestamp\":\"d0jDPt0gC9OmHmnj9yCF\",\"size\":21265,\"secret\":null,\"fileId\":\"3e4b0821-a76f-4fe4-8545-8d79f807a10e\",\"showSize\":\"21KB\",\"fileClass\":\"iconBox excelBox\"}]', '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '450', '113845370124130976,050363634136321790', NULL, '2064892343747596290', '李玲', '李玲\n17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '滋养、顺滑、柔润感；\n高级、修护感；\n东方气质', 'LYB2448ALY-忍冬复方1', 'SF1574204101171', '2026-06-23 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '价格：不超过450元\n加香量：不超过1%，\n时间：6月18前寄出\n\nBRF\n香气定位\n以忍冬花为灵感，打造具有东方气质的金色花木香调。\n整体传递：\n温润、柔和、高级、修护感、层次丰富。\n核心要求\n东方花香主体\n以忍冬花构建核心花香；\n呈现柔和、清润、温暖的花香气质；\n不偏药感、草本感。\n修护联想\n闻起来有滋养、顺滑、柔润感；\n与护发精油的修护功效形成关联。\n高级层次感\n前中后调过渡自然；\n花香丰富但不甜腻；\n留香舒适且有记忆点。\n\n复方成分由高到低排列：\n忍冬\n葡萄柚\n晚香玉\n白兰花\n弗吉尼亚雪松\n佛手柑\n粉红胡椒\n乳香\n广藿香\n丁香\n\n寄样地址：\n李玲\n17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503', '逐本-忍冬复方精油仿香_20260611', '1', '无', NULL, NULL, NULL);
