INSERT INTO `w_bo_gd_20250707155940` VALUES ('2064950413169250305', '0', '0', '16275212368889684', '赵文雅', '2026-06-11 13:58:38', '17201757871959617', '赵倩', '2026-06-12 17:08:41', '1', '2064950413328629762', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260611-0028', '2063879436679196674', '高晶纤维板-室内装修用的板材香精推荐-20260608', NULL, '1', '需求明确', '5', '香精库推荐', '502', '其他', '2027-06-08 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '赵殿勤,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200以内', '05035817013833,17400514601408872', NULL, '2063878556315758593', '刘霞', '刘霞\n13661494993\n山东省临沂市河东区汤河镇工业园区\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5137405753499', NULL, NULL, NULL, '赵殿勤,于姗姗', '产品要求。\n1留香久。越久越好。\n2香味纯正。无异味。\n3耐高温。(我厂造机械温度120度。)\n4味道有以下几种是我的需求。玫瑰。咖啡。薄荷。(薰衣草十迷迭:香)。茉莉花。竹叶香精。荷花。\n如有好的味道可以多提供一下再有自然的。\n各15克\n用途 室内装修用的板材', '推荐', '1', '无', NULL, NULL, NULL);
