INSERT INTO `w_bo_gd_20250707155940` VALUES ('2069257872859975681', '0', '0', '16455177663846080', '常晓爽', '2026-06-23 11:14:56', '17201757871959617', '赵倩', '2026-07-22 14:30:08', '1', '2069257873103241217', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260623-0011', '2068970267329155074', '戈海  DXB2517AJK--DH-M247191 香格里拉  调整', NULL, '1', '需求明确', '2', '客户老品升级', '202', '身体清洁', '2027-06-22 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '130', '1638968357988946', NULL, '2034161061858361346', '居居', '居居\n13922118445\n广州市天河区珠江新城华夏路富力盈通2810室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5114257846652', NULL, NULL, NULL, '何家文', '需求：客户反馈版本三：DXB2517AJK（DH-M247191）强度是OK的，用在喷雾产品也是没问题的，但是应用在沐浴露（添加量1.2%）又出现跟原版DH160802K（DH-C07893）一样的返稀，版本二：JKB2490AJK（DH-A33845）用在洗护产品并没有出现返稀，就是强度不够。麻烦核实一下版本三是什么原因导致返稀。客户未来是希望用同一款香精应用在洗护沐产品和喷雾产品。\n产品：洗护沐和喷雾产品\n价格：130元\n地址：戈海居居', '戈海DH-M247191-DXB2517AJK香格里拉改进', '1', '无', NULL, NULL, NULL);
