INSERT INTO `w_bo_gd_20250707155940` VALUES ('2069309968036646914', '0', '0', '17253690046572896', '周宇', '2026-06-23 14:41:57', '113845370124130976', '彭佳庆', '2026-07-06 10:53:05', '1', '2069309968242163714', 'RUNNING', '运行中', '909783222', '评香部', '10', 'YPGD-20260623-0022', '2067093057773228033', '弗止--剑三香氛项目推荐&修改20260617', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200~300', '113845370124130976,16466317325076496', NULL, '2055159748134658049', 'jiojio', 'jiojio\n15178065377\n上海市静安区江场路1447号云芯科创中心T1号楼19楼DO事业部 jiojio，15178065377\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '【角色香】创作\nA. 叶芷清 x2\nB. 叶英 x2\nC. 谢云流 x1\nD. 李忘生 x1\n\n需求价格：200~300', 'LYA1421LLY-林间绿风1-叶英  LYA2266FLY-薄荷雪松1-谢云流  LYA2266GLY-柑橘茶香1-李忘生 \nLYA2323ELY-桂花茉莉1-叶芷清 LYA2450ALY-沙漠百合1-叶芷清    LYA2451ALY-龙脑绿茶1-叶英', '74100603680996', '2026-07-06 00:00:00', NULL, NULL, '彭佳庆,梁皓', '上海市静安区江场路1447号云芯科创中心T1号楼19楼DO事业部 jiojio，15178065377\n背景：该ip为热门武侠网游IP具有客观的消费群体与消费力度，需重点关注\n故事背景均发生于盛唐时期故可以有一些古韵在内\n需求1：\n角色香包\n（1）叶芷清：\n方案1：干桂花 茉莉 檀香 丁香\n花的占比稍微稍微高一些。柔中带刚，温柔又有点尖锐的感觉。（避免太刺激的味道，整体温柔好闻）\nLYB2323ALY 在该款茉莉香型上做增加桂花与木质焚香感，用于香包需注意扩香能力与香气舒适度\n\n方案2：粉红胡椒 沙百合 茉莉 檀香 丁香\n需求同上。想试试和人设的适配度\nLYP908BLY 这款做膏甜花香赋予感，用于香包需注意扩香能力与香气舒适度\n\n（2）叶英：\n方案1：龙井绿茶 桂花 檀木 龙脑\n突出绿茶和龙脑，要雨后空山，古寺听茶的感觉（不要太清凉）\nLYP908BLY增加些许草本凉感与绿意可以往玉龙茶方向靠一靠，用于香包需注意扩香能力与香气舒适度\n\n方案2：紫罗兰叶 鸢尾花 玫瑰 檀香木 雪松\n整体想要偏中性男香的感觉，元素可叠加或者做取舍\nLYP1421DLY  需要优化价格并增强扩香可以优化其框架，用于香包需注意扩香能力与香气舒适度\n\n（3）谢云流：\n佛手柑 苦艾草 薄荷叶 雪松 愈创木 琥珀 松木\n希望雪松、薄荷叶是主导，苦艾次之。佛手柑前调做铺垫，少放愈创木（烟熏感的香味大众接受度比较低）！整体是从冷到暖的感觉\nLYP2266DLY/LYP2266DLY 二选一修改 需要优化价格并增加木质暖感元素，用于香包需注意扩香能力与香气舒适度\n\n(4)李忘生：\n佛手柑 青柠 茶香 沉香 檀香 柏木\n希望闻起来要干净，清风拂面。突出柑橘和茶香，不要太厚重，慢慢渗透出来沉香和檀香。整体闻起来既有少年感，又有历经沉淀的稳重\nLYP2266DLY 需要优化价格增加茶香与沉檀元素，可增加适当皂感优化，用于香包需注意扩香能力与香气舒适度\n\n需求2：\n场景无火藤条香方向\n方案1：\n前调：香柠檬 绿叶\n中调：铃兰 百合 羽扇豆花\n后调：蜂蜡 麝香 开司米木\n需要清新感。香柠檬的占比可以比较高突出铃兰和百合，不要太甜腻。如果太甜可以加点别的中和一下。\n希望贴肤感强\n整体偏向于白花+木质调。扩散性好，白花部分不要闻起来腥。\nLYP2401ALY 适当优化与原版做出区别即可，产品用于无火藤条需注意扩散能力\n\n方案2：\n前调：柑橘、醛\n中调：玫瑰 百合 羽扇豆花\n后调：蜂蜡 紫罗兰叶\n想要那种淡淡香皂的感觉。\n突出玫瑰和羽扇豆花。想要紫罗兰叶中和一下甜度和粉感\n扩散性好，不要闻起来是劣质护肤品的感觉。有一点脂粉感的玫瑰的感觉\nLYP1476ALY 增加玫瑰花瓣的花香与馥郁感，不要过于甜腻，产品用于无火藤条需注意扩散能力\n\n方案3：\n前调：绿叶 梨\n中调：郁金香 铃兰 羽扇豆花\n后调：蜂蜡 白麝香 雪松 龙涎\n青梨感花香为主，水润、清澈、略带绿意的清新花香。香调更有层次，扩香更好\nLYB1681CLY 增加梨与绿叶感，产品用于无火藤条需注意扩散能力\n\n需求3：\n门派香囊\n香调元素：薰衣草 甘草 薄荷 白芷\n需要精油感重，有类似疗愈赶在内，符合游戏内设定的治疗类技能\nLYP1181BLY 该香型为薰衣草在适当加入草本药香\n\n需求价格：200~300\n产品角色香与门派香用于香包，场景香用于无火藤条需注意溶剂！！！！！！\n需要提供15%香水加香产品\n香精10g即可\n需求时间：最晚7.3一定寄出', '弗止--剑三香氛项目推荐&修改20260617', '1', '无', NULL, NULL, NULL);
