INSERT INTO `w_bo_gd_20250707155940` VALUES ('2069712124078182402', '0', '0', '17253690046572896', '周宇', '2026-06-24 17:19:58', '17201757871959617', '赵倩', '2026-07-23 17:13:50', '1', '2069712124367585282', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260624-0013', '2069333851070517249', '星宇昊海--新品蜡烛推荐&修改20260623', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '500以内', '113845370124130976,16466317325076496', NULL, '2034161061669617665', '李俊', '李俊\n18117207858\n上海市黄浦区淮海中路 627号WeWork 4F， 18117207858    李俊\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5113156377915', NULL, NULL, NULL, '彭佳庆,梁皓', '1.  蜜瓜+微量的葡萄（不想有化工感）+玫瑰。\n蜜瓜推荐：LYP485ALY、JKC1246DJK、LJC1226BLJ\n\n 2.苔洇碧染，你试试看再给我的两个苔藓味道里，加点青草和雨后泥土的味道吧，现在没有雨后的感觉，只有凉意，没有水汽和湿气。     \n苔藓推荐：LCC1236ALC、LYP1504ALY\n番茄叶推荐：LYC2065ALY、LYP1142BLY\n\n3.  馕与核桃：新疆美食调\n核桃香型推荐：LJP1190ALJ\n\n4.  胡杨红柳： 模拟意象中的胡杨和红柳的味道吧。        大漠苍凉感的木质调+顽强的生命力的感觉（就是干燥中又带着点清新感，类似沙漠绿洲的感觉 ）\n胡杨红柳：LYP2375BLY\n\n5. 生生不息：水润生瓜+竹笋+青涩瓜藤+大地，或者加点之前的松针的味道+藤（那种有点青涩的藤，，加青草或者菊花的那个味道？），  松柏+岩兰草+苔藓+荷花\n瓜香推荐：LYP1555ALY\n\n6. 秦简汉牍：药感墨香木质调（少量的香芒+少量花椒；松烟墨（如何实现？松焦油，松香油？  ）+麝香+丁香；  干燥木质调（柏木、创愈木可以带一点淡淡的干竹子香）\n秦简汉牍：LYP735ALY、LYP1159BLY\n竹香：LYP1652ALY\n\n7. 苍松翠柏  松木+柏树 松针+柏叶 加点松果 松子的味道，也是木质调。\n松针推荐：LYP1468BLY\n优先提供有库存版本\n产品用于蜡烛产品内\n需求价格：500以内\n先推荐香型确认后需要修改\n需求时间：6.26\n寄样地址：上海市黄浦区淮海中路 627号WeWork 4F， 18117207858 李俊', '星宇昊海--新品蜡烛推荐&修改20260623', '1', '无', NULL, NULL, NULL);
