INSERT INTO `w_bo_gd_20250707155940` VALUES ('2069973923704852482', '0', '0', '17253690046572896', '周宇', '2026-06-25 10:40:16', '113845370124130976', '彭佳庆', '2026-07-01 15:17:37', '1', '2069973923906174977', 'RUNNING', '运行中', '909783222', '评香部', '8', 'YPGD-20260625-0013', '2069352132498149378', '回家本能--植物系列主题新品推荐&修改20260623', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"桃子乌龙（黑客）.xlsx\",\"timestamp\":\"IvsJN1BDF8NTUujpHBgk\",\"size\":17616,\"secret\":null,\"fileId\":\"d7bf021f-7ef1-4cbd-809c-482c9b2216da\",\"showSize\":\"17KB\",\"fileClass\":\"iconBox excelBox\"}]', '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400以内', '113845370124130976,16466317325076496', NULL, '2034161062130991106', 'Eddy', 'Eddy\n19957842610\n浙江省宁波市海曙区柳汀街297号（星悦中心8号楼）2309   eddy 19957842610\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '【桃花灼灼】- 进样仿香，样品名 <桃子乌龙>\n\n之前样参考：LYP1557CLY  千金岁岁1（香水）； LYP1557DLY  千金岁岁2（香水）', 'LYP2453ALY-桃子乌龙1（香水）', '74100603680992', '2026-07-01 00:00:00', NULL, NULL, '彭佳庆,梁皓', 'Eddy收\n根据客户提供brief进行第一批推荐后续根据需求进行优化修改\n1、发财树 · MONEY TREE\n前调：鸢尾根、纸莎草、干燥琥珀\n中调：乳香、没药、龙涎香醚\n后调：雪松、檀木、开司米木\n推荐：LYP735ALY、YQP092AYQ、LCP866ALC\n\n2、桃花灼灼\n前调：桃花、杏子\n中调：白桃、番茄叶、玫瑰、茉莉\n后调：青草、桃叶、橡木苔\n推荐：黑宫桃花，需要调香师根据已有GC谱图仿香提供\n\n3、红菜头 · GARDEN RADISH\n前调：湿润泥土、胡萝卜籽、青绿根茎\n中调：甜菜汁、红浆果、紫罗兰叶\n后调：香根草、雪松、白麝香\n推荐：DHA2030ADH、LYP636BLY\n\n4、椰子树 · COCONUT PALM\n前调：青椰子水、海盐、柠檬草\n中调：椰肉、绿叶、鸡蛋花\n后调：浮木、白麝香、檀香\n推荐：LJP565ALJ、SYP968BSY\n\n5、小葵 · SUN FLOWER\n前调：青绿茎叶、柠檬、佛手柑\n中调：向日葵花、橙花、蜂蜜\n后调：香草、白麝香、葵花籽\n推荐：LYP928BLY、LYP926ALY、LYP1681BLY、LYA2274ALY、LYP883BLY\n\n客户产品用于香珠、香氛喷雾\n需求价格：400以内\n需求时间：6.26\n第一波推荐为参考香气，只需寄香精即可\n后续正式修改样品需要15%香水加香产品', '回家本能--植物系列主题新品推荐&修改20260623', '1', '无', NULL, NULL, NULL);
