INSERT INTO `w_bo_gd_20250707155940` VALUES ('2070092557974491137', '0', '0', '16455177663846080', '常晓爽', '2026-06-25 18:31:41', '17201757871959617', '赵倩', '2026-07-08 09:41:12', '1', '2070092558234533890', 'RUNNING', '运行中', '909783222', '评香部', '7', 'YPGD-20260625-0044', '2069356237400559618', '博维  洗衣凝珠新品推荐', NULL, '1', '需求明确', '5', '香精库推荐', '102', '新型织物洗护', '2027-06-23 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '1', '1638968357988946', NULL, '2069356019644878849', '何家文', '何家文\n18620840308\n广东省广州市越秀区中山六路232-258号越秀新都会大厦5层 05-122房\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5110934370859', NULL, NULL, NULL, '何家文', '要5套样品 做成凝珠\n\n洗衣凝珠		DXF2125FDX	纯白茉莉\n洗衣凝珠		SYF2543BJK	清茶檀香\n洗衣凝珠		SYF2535BSY 	琥珀芒夏\n洗衣凝珠		DXF2477ADX	苹果鸢尾\n洗衣凝珠		DXF2479ADX	无花果茉莉\n\n地址：广东省广州市越秀区中山六路232-258号越秀新都会大厦5层 05-122房  何家文18620840308', '博维Q2洗衣凝珠新品推荐', '2', '加香', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2070315291052593153', '0', '0', '05035817329389', '刘畅', '2026-06-26 09:16:45', '17201757871959617', '赵倩', '2026-07-01 10:36:24', '1', '2070315291346190338', 'RUNNING', '运行中', '12377314', 'DHFF', '3', 'YPGD-20260626-0001', '2070042632565805058', '（非常紧急）沃德绿精油产品调整-提振 26-06-25', NULL, '1', '需求明确', '1', '客户新品开发', '207', '其他个人护理', '2027-06-25 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000', '02461210300720808373', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5117713082668', NULL, NULL, NULL, '余鹏程', '原版本：DH-A27729 提振精油（改版4#） LQP2055ALQ\n现客户根据出口国当地法规要求，对配方调整有新需求，具体内容如下：\n药剂师审查了所提供的原料IFRA证书（第51号修正案），并从中识别出两种次要成分，需对其浓度进行调整，以确保符合拉丁美洲各国的法规要求（依据安第斯共同体第833号决定）：\n1) 佛手柑果油（成分编号4）： 要求将其浓度设定为1.500%（重量/重量），以安全地符合相关限制要求，并降低与呋喃香豆素相关的风险。此外，我们要求该工厂以书面形式更正/确认，该批佛手柑油不含呋喃香豆素（FCF / furocoumarin-free）。\n2)亚香茅（CYMBOPOGON NARDUS）油： CYMBOPOGON NARDUS OIL（成分编号11）： 要求将其浓度从0.10%降至0.050%（百分比），以使产品符合IFRA第3类（指尖留置式应用）的严格限值（最高允许浓度为0.07222%），从而确保产品符合相关规定。 为了在不改变活性成分混合物的感官特性及功能性的前提下，将质量平衡精确维持在100.00%，\n建议将总减量（0.275%（p/p））通过增加主要成分（甜杏仁油）的含量来弥补，将其比例从85%提高至85.275%。 附上配方第3版修订稿，供与制造商进行验证管理之用。\n\n******样品中文名可取《清新精油3.0》，样品需20g，完成后可直接寄给上海有息，并需要我司出具“不含呋喃香豆素”盖章声明\n有息收货地址：上海市闵行区华宁路3333号海联智谷科创产业园28号楼4楼任兰兰13262964371', '沃德绿精油产品调整-提振', '1', '无', NULL, NULL, NULL);
