INSERT INTO `w_bo_gd_20250707155940` VALUES ('2071409912784605185', '0', '0', '17253690046572896', '周宇', '2026-06-29 09:46:23', '113845370124130976', '彭佳庆', '2026-08-24 18:02:26', '1', '2071409913036259330', 'RUNNING', '运行中', '909783222', '评香部', '13', 'YPGD-20260629-0005', '2070345618332569601', '不蟹--雪松王座仿香20260626', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"雪松王座.xlsx\",\"timestamp\":\"lu9uqTiECCtsspPsrV2d\",\"size\":21387,\"secret\":null,\"fileId\":\"6735bf19-37f2-4ae5-80cd-d87c6b44e853\",\"showSize\":\"21KB\",\"fileClass\":\"iconBox excelBox\"}]', '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400', '16466317325076496,113845370124130976', NULL, '2054826672351305730', '韩-高尚领域', '韩-高尚领域\n13818000683\n上海市普陀区曹杨路1788号高尚领域T9栋212室 韩 13818000683\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP2457CLY  凉感药香过于明显，需追加头香的相似度\n更新价格 1000以内', 'LYP2457CLY-雪松王座2\n\nLYP2457DLY-雪松王座3\n', 'SF0210007175380/SF0211007159958', '2026-08-24 00:00:00', NULL, NULL, '梁皓,彭佳庆', '需要寄两个地址每个地址各一套加香产品\n地址1：上海上海市闵行区景丽苑183号201 韩 13818000683\n地址2：浙江省杭州市滨江区长河古镇泽街23-2 东方鼻子 13983703663蟹老板\n根据客户提供样品进行仿香\n要求还原度高\n产品名称：雪松王座\n客户产品用于香氛喷雾内\n需求价格：400\n需求时间：7.8\n需要15%香水加香产品', '不蟹--雪松王座仿香20260626', '1', '无', NULL, NULL, NULL);
