INSERT INTO `w_bo_gd_20250707155940` VALUES ('2071799909798891521', '0', '0', '17253690046572896', '周宇', '2026-06-30 11:36:05', '17253690046572896', '周宇', '2026-08-17 10:37:16', '1', '2071799909987631105', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260630-0020', '2071445508903129089', '诗肤理--白兰复配精油优化升级20260629', NULL, '1', '需求明确', '1', '客户新品开发', '205', '面部护肤', '2028-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '8000', '113845370124130976,16466317325076496', NULL, '2034161060537155586', 'Elaine*', 'Elaine*\n18621746130\n上海市闵行区申长路1588弄中骏广场一期01号楼平安财富中心3A07室  Elaine 18621746130\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP1736ELY在原版去掉栀子油，加其他天然油，升级修改\n0.2%和0.5%两个加香浓度产品\n08/26\n-------------------\n3个方向，8000块，开配方；\n主框架为1款，加苦橙叶为1款，第3个方向 待定', 'LYS2455ALY-天竺白兰1（面霜）LYS2455BLY-天竺白兰2（面霜）LYS2455CLY-天竺白兰3（面霜）LYS2455DLY-天竺白兰4（面霜）\n', '74100603681617', '2026-07-17 00:00:00', NULL, NULL, '彭佳庆,梁皓', '收件地址：上海市闵行区申长路1588弄中骏广场一期01号楼平安财富中心3A07室 Elaine 18621746130\n需求：LYP1736ELY 原版客户反馈栀子在内表现不明显现去掉栀子油，以白兰作为主要香气香韵\n需要盖住base的基料味，已联系客户提供相应base\n需注意闪点问题！！！ 需要全开配方！！！\n按客户需求新升级版配方框架主题如下\n以白兰+天竺葵+榄香/乳香 为主线来调整\n需要给客户提供方3个方向优化\n客户主框架为1款，加苦橙叶为1款，第三方向由调香评香确定\n要增加香气表现力，降低些添加量，成本优化\n需求价格：8000元\n添加量以我们测试效果为主\n大概范围：0.08%~0.5%\n需要给客户提供至少两个适宜的加香产品供客户选择\n需求时间：暂定7.15主要看加香后的base适配性与遮盖力表现力', '诗肤理--白兰复配精油优化升级20260629', '1', '无', NULL, NULL, NULL);
