INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072513363220353025', '0', '0', '16455177663846080', '常晓爽', '2026-07-02 10:51:06', '16455177663846080', '常晓爽', '2026-07-21 16:08:03', '1', '2072513363526533122', 'SUCCESS_END', '成功结束', '909783222', '评香部', '2', 'YPGD-20260702-0012', '2072126375019401217', '亿达-调整C30024-0701', NULL, '99', '关闭', '3', '双马香精升级', '201', '头发洗护', '2027-07-01 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '邢芬,郭治爽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '16855125875633810,04476151371724', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '邢芬,郭治爽', 'C30024 ，调整配方\n客户反映加到洗发水里边稀了，看看能不能修改一版\n  洗发水加香量是0.5%    150元以内\n\n高知朋 17329976779\n广州市白云区钟落潭镇金盆村政农路6号广州亿达化妆品有限公司(实验室收)', 'C30024', '1', '无', NULL, NULL, NULL);
