INSERT INTO `w_bo_gd_20250707155940` VALUES ('2073948951421112321', '0', '0', '05035817329389', '刘畅', '2026-07-06 09:55:37', '17201757871959617', '赵倩', '2026-07-06 17:50:52', '1', '2073948951597268993', 'RUNNING', '运行中', '12377314', 'DHFF', '3', 'YPGD-20260706-0009', '2064914760159186946', '天津下午士多香精推荐26-06-11', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-06-11 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400', '02461210300720808373', NULL, '2064913713722281985', 'Kim张', 'Kim张\n13163106577\n天津天津市西青区西营门街道    智慧山艺术中心北侧，一层室外下午士多（注意找红色楼梯）\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5117229248026', NULL, NULL, NULL, '余鹏程', '1、附件图片中几款按香调找香，注意样品与图片内命名方式一致\n2、请推荐茶香香型3~5款，需要香氛感、高级感好\n3、我司最新空间香氛香型推荐5~8款\n以上产品用于无火，价位400左右', '天津下午士多香精推荐', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2073950949881139201', '0', '0', '16455177663846080', '常晓爽', '2026-07-06 10:03:33', '16455177663846080', '常晓爽', '2026-07-06 10:39:24', '1', '2073950950107627522', 'SUCCESS_END', '成功结束', '909783222', '评香部', '2', 'YPGD-20260706-0010', '2063879436679196674', '高晶纤维板-室内装修用的板材香精推荐-20260608', NULL, '99', '关闭', '5', '香精库推荐', '502', '其他', '2027-06-08 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '赵殿勤,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200以内', '05035817013833,17400514601408872', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '赵殿勤,于姗姗', '产品要求。\n1留香久。越久越好。\n2香味纯正。无异味。\n3耐高温。(我厂造机械温度120度。)\n4味道有以下几种是我的需求。玫瑰。咖啡。薄荷。(薰衣草十迷迭:香)。茉莉花。竹叶香精。荷花。\n如有好的味道可以多提供一下再有自然的。\n各15克\n用途 室内装修用的板材', '高晶纤维板', '1', '无', NULL, NULL, NULL);
