INSERT INTO `w_bo_gd_20250707155940` VALUES ('2073979417197006849', '0', '0', '16455177663846080', '常晓爽', '2026-07-06 11:56:40', '16455177663846080', '常晓爽', '2026-07-08 11:57:50', '1', '2073979417448660994', 'SUCCESS_END', '成功结束', '909783222', '评香部', '2', 'YPGD-20260706-0019', '2056242808708096001', '培蘑--百香果创香20260518', NULL, '99', '关闭', '1', '客户新品开发', '301', '个人香氛', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000以内', '113845370124130976,16466317325076496', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '彭佳庆,梁皓', 'SYP2043DSY 百香果香基\n\n1.加入多汁、精纯的果香状态。\n百香果香基未经稀释的状态是最好的，果香饱满，目前果香的状态比较偏平，经过多轮普通消费者测试，大家反馈平平。增\n加多汁意向可在前调迅速抓住鼻子。\n2.降糖\n百香果被Pape Moe定位为热卖选题（同草莓、芭乐）为了更好的销量希望适当降低甜度，去适配更多的中国消费者。\n3.多样的搭配增加耐闻度，与市面上单一果香品牌拉开距离\n我们提出一些搭配思路供调香师参考\nA.焚香+百香果\n轻盈的日式焚香与百香果的热情碰撞\nB.草本+百香果\n罗勒、尤加利、薄荷、斑斓一些比较受欢迎的草本都可以尝试。\nC.辛香+百香果\n一些比较芳香偏绿的辛香，芫荽、黑胡椒、小豆蔻、月桂叶等等\n\n需要根据客户需求提供3个方向递样\nSYP2043DSY 百香果香基整体减低甜感，增加热带果感\n\n1、焚香+百香果\n2、草本+百香果\n3、辛香+百香果\n\n需求价格：2000以内\n需要15%香水加香产品', '培蘑百香果创香', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2073982549784252417', '0', '0', '16825006662777257', '齐钰', '2026-07-06 12:09:07', '17201757871959617', '赵倩', '2026-07-14 14:56:12', '1', '2073982550019129346', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260706-0020', '2072309027999567873', '嘉美  14款大牌香水仿香项目', NULL, '1', '需求明确', '5', '香精库推荐', '301', '个人香氛', '2027-07-01 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文,王鑫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '无', '1638968357988946,0549274114954944', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5157197188293', NULL, NULL, NULL, '何家文,王鑫', '香水：奥费恩、蒂菩提克玫瑰之水、阿玛尼白金鳝、午后伯爵、罗意威黑色圆舞曲、尼亚雷香水、柳叶与琥珀、马吉拉温暖壁炉、闻献羽化仙、静骨、苹果白兰地、馥马尔一轮玫瑰、Diptyque纸上、芭乐茉莉\n全部要最高版本\n产品：香水（添加量20%）', '现有库存', '1', '无', NULL, NULL, NULL);
