INSERT INTO `w_bo_gd_20250707155940` VALUES ('2074413956327264257', '0', '0', '17253690046572896', '周宇', '2026-07-07 16:43:23', '113845370124130976', '彭佳庆', '2026-07-15 10:29:50', '1', '2074413956549558273', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260707-0027', '2074062387480088578', 'EIOS秋冬新品栗子', NULL, '1', '需求明确', '1', '客户新品开发', '203', '身体护肤', '2026-07-20 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王晔,梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '1000', '17127345845433575,16466317325076496,113845370124130976', NULL, '2055099783718068225', '李先生', '李先生\n15061883002\n上海市长宁区长宁国际T4栋12层\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '1585B 桦痕 基础上修改\n\n最后确认样 -- LYP1585CLY', 'LYP2462ALY-炭火烤栗1（香水）\nLYP2468ALY-烟熏烤栗1（香水）', '闪送', '2026-07-15 00:00:00', NULL, NULL, '王晔,梁皓,彭佳庆', '手霜、唇膏！！、指油、沐浴露----秋冬栗子香气\n不想太过于美食调，需要有点木质调平衡一下\n7月20日前定，产品上线时间赶在10月中\nMaison Margiela温暖壁炉可以是一个方向\n另外客户提到DVN哈瓦那金，烟熏感带有奶油，带点点烟草、杏仁，是他想要的感觉\n需求价格：400~1000\n需求时间：最晚7.15寄出\n需要做加香测试后递出\n寄样香精20g\n寄给长宁国际李先生', 'EIOS秋冬新品栗子_260707', '1', '无', NULL, NULL, NULL);
