INSERT INTO `w_bo_gd_20250707155940` VALUES ('2074686457435377666', '0', '0', '16825006662777257', '齐钰', '2026-07-08 10:46:12', '17201757871959617', '赵倩', '2026-07-13 17:03:33', '1', '2074686457783500802', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260708-0007', '2074421648517222402', '璞菏--无垢木与雪松、漫步间出口香水油仿香优化20260707', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200以内', '113845370124130976,16466317325076496', NULL, '2076573805064474626', '周雯倩', '周雯倩\n15664110927\n上海市奉贤区环城西路3111号8号璞菏（放入丰巢边上的蓝色专用框）\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5157237107923', NULL, NULL, NULL, '彭佳庆,梁皓', '【木质调：参考参考品牌 祖玛珑·无垢木与雪松】三个方向，谱图仿香，样品各50g\n前调：青苔芳香、肉桂\n中调：日本桧木、丁香、英国薰衣草\n后调：雪松、广藿香、冬加豆\n\n寄：周雯倩，15664110927，上海市奉贤区环城西路3111号8号璞菏（放入丰巢边上的蓝色专用框）\n客户有两款仿香需求，目标价格需要控制在200元/kg以下\n这是一款出口至东南亚的香水滚珠油产品，请在开发香精时做好相关的符合出口东南亚国家的相关法规风险把控\n下方是香型需求\n根据产品定位规划，产品以年轻时尚为调性，以亲民的价格服务东南亚年轻群体，满足年轻消费者们对沙龙香的追求，竞品及香型方向如下\n\n【竞品】\n1. “东南亚（泰国）当地” PANPURI\n2. “中国本地” 闻献\n\n【香型方向·沙龙香类型】\n1. 木质调：参考参考品牌 祖玛珑·无垢木与雪松\n前调：青苔芳香、肉桂\n中调：日本桧木、丁香、英国薰衣草\n后调：雪松、广藿香、冬加豆\n2. 花香调：参考品牌 馥马尔·漫步间\n前调：紫丁香、黄瓜\n后调：雪松、麝香\n\n实际需求：客户出口东南亚需注意出口法规是否符合标准\n香水油加香量为15~25%\n香水油溶剂为GTCC（辛癸酸甘油酯）\n需注意加香量以及溶剂适配性问题\n需要做仿香以及两个仿香基础上的加强版\n期望留香时长：6-8h\n需要每款寄样50g\n需求时间：7.17前寄出\n需求价格：200以内', '无垢木与雪松', '1', '无', NULL, NULL, NULL);
