INSERT INTO `w_bo_gd_20250707155940` VALUES ('2076560266199289858', '0', '0', '17253690046572896', '周宇', '2026-07-13 14:52:03', '17201757871959617', '赵倩', '2026-07-13 16:32:55', '1', '2076560266505469953', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260713-0024', '2074707826713808897', '德清香悦--杜松薰衣草&香链广州香精推荐20260707', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200~300', '113845370124130976,16466317325076496', NULL, '2074706508565696513', '杨海波', '杨海波\n15158104329\n浙江省湖州市德清县雷甸镇启航路168号A幢5楼   杨海波 15158104329\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '【杜松薰衣草】推荐\n需要 3款，300以内，20g - 50g 寄样；\n\n*LYP1475BLY -- IFRA 10A,  10%', NULL, 'SF5115144972359', NULL, NULL, NULL, '彭佳庆,梁皓', '寄样：浙江省湖州市德清县雷甸镇启航路168号A幢5楼 杨海波 15158104329\n需求1：优先寄样客户需要杜松薰衣草香型推荐\n需要3款推荐\n需求价格：300以内\n\n需求2：香链广州出口香型推荐\n冬季乌木 LCC2055ILC\n白色鸢尾 JKC2341BJK\n棉绒回忆 DXC2285ADX\n神秘女士 HDC2232AHD\n芒果冰 DXC2290CDX\n藏红花檀木 LJC2344ALJ\n极地 FLC2010AFL\n乡间市集 SYC2377BSY\n奇妙松茸 LQC2092ALQ\n融冬蜜语 HDC2260AHD\n绿野呼吸 LJC2132CLJ\n薄荷摩卡 FLC2009AFL\n蓝莓麦芬 LJC2355ALJ\n乖乖乳果 JKC2390AJK\n哈密瓜奶油苏打 JKC1246DJK\n海盐花生酱 SYC2443ASY\n香草冰糖 SYC2204CSY\n糖煮栗子 JKC2393CJK\n需求时间：优先挑选杜松薰衣草寄样\n需要50g样品\n需求时间：7.10\n客户产品为家居香氛类', '德清香悦--杜松薰衣草&香链广州香精推荐2_20260707', '1', '无', NULL, NULL, NULL);
