INSERT INTO `w_bo_gd_20250707155940` VALUES ('2076940863031726082', '0', '0', '16275212368889684', '赵文雅', '2026-07-14 16:04:24', '17201757871959617', '赵倩', '2026-07-15 17:51:41', '1', '2076940863233048578', 'RUNNING', '运行中', '909783222', '评香部', '8', 'YPGD-20260714-0017', '2075477707730178050', '如初-四个样品需求-20260710', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-07-10 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '0549274114954944,17400514601408872', NULL, '2077221282423754754', '李微', '李微\n13833284681\n保定市满城区欧诗琳节能材料科技有限公司\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5118246450994', NULL, NULL, NULL, '王鑫,于姗姗', 'Sample 1: Sea Salt + Caramel\nInspirational notes: Sea Salt, Caramel. Lemon, Pink Pepper, Jasmine, Sea Grass, Cedar\nSample 2: Christmas Tree 1\nTop notes: Juniper berries, Basil, Lemon, Lavender, Bergamot\nHeart notes: Pine needles, Clary sage, Clove, Caraway, Geranium\nBase notes: Cedar, Oakmoss, Musk, Amber, Tonka bean\nSample 3: Christmas Tree 2\nPlease try to create smell of a christmas tree. We may use such fragrances as: Eucalyptus, Fir, Resin, Frankincense, Cedar, Spruce etc.\n样品1: 海盐 + 焦糖\n励志笔记: 海盐，焦糖。柠檬，粉红辣椒，茉莉，海草，雪松\n\n样本2: 圣诞树1\n前调: 杜松子、罗勒、柠檬、薰衣草、佛手柑\n心香: 松针，鼠尾草，丁香，香菜，天竺葵\n基调: 雪松，Oakmoss，麝香，琥珀，Tonka豆\n样本3: 圣诞树2\n请尝试制造圣诞树的气味。我们可以使用这样的香水: 桉树，冷杉，树脂，乳香，雪松，云杉等。\nSample 4: Tea\nTreat it as a reference, you may change sth:\nHoly Basil, Jasmine Blossom, Pandan Leaf, Green Mandarin Peel, Red Pepper, Benzoin of Sumatra\n样本4: 茶\n把它当作参考，你可以改变某事:\n圣罗勒，茉莉花，香兰叶，绿橘皮，红辣椒，苏门答腊安息香\n四个样品需求 用于线香\n收件人张迎春', '推荐', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2076951547031310337', '0', '0', '16455177663846080', '常晓爽', '2026-07-14 16:46:51', '17201757871959617', '赵倩', '2026-07-24 17:49:53', '1', '2076951547228438530', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260714-0018', '2075135914253733889', '山下有松--松寺修改20260709', NULL, '1', '需求明确', '3', '双马香精升级', '302', '空间香氛', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '500左右', '113845370124130976,16466317325076496', NULL, '2048619010949341186', '王妍', '王妍\n13581841518\n北京市朝阳区浩华文创园C9songmont 王妍 13581841518\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5112760701964', NULL, NULL, NULL, '彭佳庆,梁皓', '寄王妍\nLJA2216BLJ\n该款有两个修改需求\n需求1：客户要把该款修改为香氛喷雾版本，需要10A类添加量大于12%\n寄样5%香氛喷雾（待7.10确认base载体）\n需求价格：460\n\n需求2：客户反馈该款无火藤条香氛表现出色\n需要做香水版优化具体优化方向7.10会议确定\n需要做15%香水加香产品\n需求价格：500左右\n需求日期：7.24', '山下有松松寺修改', '2', '加香', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2076951610667290625', '0', '0', '17253690046572896', '周宇', '2026-07-14 16:47:07', '113845370124130976', '彭佳庆', '2026-08-20 17:20:21', '1', '2076951610893778946', 'RUNNING', '运行中', '909783222', '评香部', '27', 'YPGD-20260714-0019', '2076868954361417730', '花淇--大牌香氛推荐20260714', NULL, '1', '需求明确', '5', '香精库推荐', '301', '个人香氛', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400', '113845370124130976,16466317325076496', NULL, '2076867133320450049', '白茶', '白茶\n19921092070\n上海市闵行区金虹桥虹梅路2986弄小区10号楼304 白茶 19921092070\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP2282FLY客户确认这款清透版效过理想, 需要在此基础上 追加两个版本\n方向1：绿叶加强\n方向2：花香/白麝香加强\n\n-------- 之前信息------\nLYP2282BLY	琼轮 -- 加白柠檬和香柠檬或绿叶感，做清爽调整;', 'LYP2282FLY-琼轮6（香水）\n\nLYP2282GLY-琼轮7（香水）\nLYP2282HLY-琼轮8（香水）', 'SF1574204113076', '2026-08-20 00:00:00', NULL, NULL, '彭佳庆,梁皓', '寄：上海市闵行区金虹桥虹梅路2986弄小区10号楼304 白茶 19921092070\n推荐上半年大牌仿香\nSYP2412BSY 雪映流光\nLYP2285BLY 蜜欲之果\nLYP2281BLY 你的人生故事\nLYP2281BLY 茶瀑*\nLYP2282BLY 琼轮*\nJKP2366BJK 伦敦烟云\nLYP2307BLY 一生之水雪松\nLYP2375BLY 柳叶与琥珀*\nLYP2377BLY 奥费恩\nLJP2468BLJ 紫罗兰30\nLYP2376BLY 克罗地亚\nLYP2386BLY 化蝶女士43\nJKP2448BJK 都灵21\n需要15%香水加香产品\n需求价格400\n需求时间：7.17', '花淇--大牌香氛推荐20260714', '', '', NULL, NULL, NULL);
