INSERT INTO `w_bo_gd_20250707155940` VALUES ('2077238605331288066', '0', '0', '05035817329389', '刘畅', '2026-07-15 11:47:31', '17201757871959617', '赵倩', '2026-07-16 16:08:59', '1', '2077238605574553602', 'RUNNING', '运行中', '12377314', 'DHFF', '3', 'YPGD-20260715-0025', '2070042632565805058', '（非常紧急）沃德绿精油产品调整-提振 26-06-25', NULL, '1', '需求明确', '1', '客户新品开发', '207', '其他个人护理', '2027-06-25 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000', '02461210300720808373', NULL, '2071893784894885890', '任兰兰', '任兰兰\n13262964371\n上海市闵行区华宁路3333号海联智谷科创产业园28号楼4楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5159789625299', NULL, NULL, NULL, '余鹏程', '【2026.7.15 修改桧木油，一版不加，一版加客户提供桧木油。】\n原版本：DH-A27729 提振精油（改版4#） LQP2055ALQ\n现客户根据出口国当地法规要求，对配方调整有新需求，具体内容如下：\n药剂师审查了所提供的原料IFRA证书（第51号修正案），并从中识别出两种次要成分，需对其浓度进行调整，以确保符合拉丁美洲各国的法规要求（依据安第斯共同体第833号决定）：\n1) 佛手柑果油（成分编号4）： 要求将其浓度设定为1.500%（重量/重量），以安全地符合相关限制要求，并降低与呋喃香豆素相关的风险。此外，我们要求该工厂以书面形式更正/确认，该批佛手柑油不含呋喃香豆素（FCF / furocoumarin-free）。\n2)亚香茅（CYMBOPOGON NARDUS）油： CYMBOPOGON NARDUS OIL（成分编号11）： 要求将其浓度从0.10%降至0.050%（百分比），以使产品符合IFRA第3类（指尖留置式应用）的严格限值（最高允许浓度为0.07222%），从而确保产品符合相关规定。 为了在不改变活性成分混合物的感官特性及功能性的前提下，将质量平衡精确维持在100.00%，\n建议将总减量（0.275%（p/p））通过增加主要成分（甜杏仁油）的含量来弥补，将其比例从85%提高至85.275%。 附上配方第3版修订稿，供与制造商进行验证管理之用。\n\n******样品中文名可取《清新精油3.0》，样品需20g，完成后可直接寄给上海有息，并需要我司出具“不含呋喃香豆素”盖章声明\n有息收货地址：上海市闵行区华宁路3333号海联智谷科创产业园28号楼4楼任兰兰13262964371', '沃德绿精油产品-提振修改桧木油', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2077238841172807681', '0', '0', '17253690046572896', '周宇', '2026-07-15 11:48:28', '113845370124130976', '彭佳庆', '2026-07-23 15:56:10', '1', '2077238841395101698', 'RUNNING', '运行中', '909783222', '评香部', '12', 'YPGD-20260715-0026', '2077234903405023234', '云檀修改-逐本（重要）', NULL, '1', '需求明确', '1', '客户新品开发', '204', '面部清洁', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '800', '113845370124130976,050363634136321790', NULL, '2064892343747596290', '李玲', '李玲\n17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '样1 -- 护肤级，保留原有框架，微调升级 >> 更草本清新、减白花+减甜\n样2 -- 食品级，依反馈意见调整；\n', 'LYS1696KLY-云檀2（面霜）\n\nLYR1696MLY-云檀3（口腔）\nLYS1696NLY-云檀4（面霜）', 'SF1574204101578', '2026-07-23 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '云檀的香精需要在原来那款（花草玫语 LYP1696GLY）的基础上做调整，价格在800/KG以内。\n调整方向如下：\n1、改善现有尖锐白兰调引发的刺鼻、头晕、塑料感、汽油味等负面反馈，调整香味更柔和化\n2、保留原有白檀尾调，前调改为复合白花香（白兰+茉莉+栀子）\n3、调整后需保持与现有香调的基础轮廓一致，不能出现太大的差异\n4、需要口唇可用\n\n应用：卸妆油/卸妆膏\n价格：800以内\n时间：7月17前（尽量）\n香精：10ml\n备注：需要做两个版本，一个是原香精基础上优化，另一个尽量贴合修改要求的食品级版本\n寄样地址：\n李玲17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503', '云檀修改-逐本（重要）_20260715', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2077243261897920514', '0', '0', '16275212368889684', '赵文雅', '2026-07-15 12:06:02', '17201757871959617', '赵倩', '2026-07-15 13:58:19', '1', '2077243262099243010', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260715-0027', '2077214814937010178', '金王-香薰项目20260715', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '240元/公斤', '17400514601408872,05035817437137', NULL, '2034161064601436162', '京京', '京京\n18354293315\n山东青岛市市南区福泰广场B座24层金王\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5157347319748', NULL, NULL, NULL, '于姗姗,宣二鹏', '香薰项目：\n1.需要檀香味 价格240元/公斤以下。乐总香水品牌的可以推荐。\n2.爆款香水香精可以用于香薰价格240元/公斤以下\n3.客户需求时间：20260718前寄出\n备注：需要基础测试', '推荐', '1', '无', NULL, NULL, NULL);
