INSERT INTO `w_bo_gd_20250707155940` VALUES ('2077637065935147010', '0', '0', '16455177663846080', '常晓爽', '2026-07-16 14:10:52', '17201757871959617', '赵倩', '2026-07-17 17:28:38', '1', '2077637066165829633', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260716-0017', '2074062387480088578', 'EIOS秋冬新品栗子', NULL, '1', '需求明确', '1', '客户新品开发', '202', '身体清洁', '2026-07-20 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王晔,梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '1000', '17127345845433575,16466317325076496,113845370124130976', NULL, '2055099783718068225', '李先生', '李先生\n15061883002\n上海市长宁区长宁国际T4栋12层\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5159060325343', NULL, NULL, NULL, '王晔,梁皓,彭佳庆', 'FLB2417AFL调整并降价\n手霜、唇膏！！、指油、沐浴露----秋冬栗子香气\n不想太过于美食调，需要有点木质调平衡一下\n7月20日前定，产品上线时间赶在10月中\nMaison Margiela温暖壁炉可以是一个方向\n另外客户提到DVN哈瓦那金，烟熏感带有奶油，带点点烟草、杏仁，是他想要的感觉\n需求价格：400~1000\n需求时间：最晚7.15寄出\n需要做加香测试后递出\n寄样香精20g\n寄给长宁国际李先生', '栗子调整', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2077637989277618178', '0', '0', '16455177663846080', '常晓爽', '2026-07-16 14:14:32', '17201757871959617', '寄样员', '2026-08-21 14:36:13', '1', '2077637989487329281', 'RUNNING', '运行中', '909783222', '评香部', '16', 'YPGD-20260716-0018', '2074062387480088578', 'EIOS秋冬新品栗子', NULL, '1', '需求明确', '1', '客户新品开发', '202', '身体洗护', '2026-07-20 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王晔,梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '1000', '17127345845433575,16466317325076496,113845370124130976', NULL, '2055099783718068225', '李先生', '李先生\n15061883002\n上海市长宁区长宁国际T4栋12层\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5156254184792', NULL, NULL, NULL, '王晔,梁皓,彭佳庆', '我想栗子的方向多增加一个，毛栗子的感觉，刚被捡起来的栗子\n秋天早上阳光很好的时候，一个男生穿着羊毛的针织衫，裹着一条带着泥土的围裙，穿着皮靴，在家里的庄园里捡掉落在地上的栗子，占着一些泥土的香气跟风感，还有植物的原生气味\n生栗子的甘甜感，果实感,就是清甜的木质香的主韵，有点绿但整体还是偏暖', '栗子新品修改', '1', '无', NULL, NULL, NULL);
