INSERT INTO `w_bo_gd_20250707155940` VALUES ('2079393183652876289', '0', '0', '17253690046572896', '周宇', '2026-07-21 10:29:03', '113845370124130976', '彭佳庆', '2026-07-27 12:32:43', '1', '2079393183891914753', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260721-0004', '2079084615510773761', 'Eios--香槟葡桃唇部用修改20260720', NULL, '1', '需求明确', '1', '客户新品开发', '206', '口腔护理', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '500以内', '113845370124130976,16466317325076496', NULL, '2074330511378993153', '陆敬亭', '陆敬亭\n18522526171\n上海市青浦区沪青平公路3938弄8栋（科黛）陆敬亭 18522526171\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '先做3个方向，参考配方 LYR2339ALY\n-紫葡萄香槟（淡酒感）\n-绿葡萄香槟（淡酒感）\n-红葡萄酒（浓酒感）', 'LYR1751BLY-紫葡萄1（唇膏）\n\nLYR1751CLY-红葡萄1（唇膏）', 'SF1574204101639', '2026-07-24 00:00:00', NULL, NULL, '彭佳庆,梁皓', '寄：陆敬亭18522526171上海市青浦区沪青平公路3938弄8栋（科黛）\n根据客户需求递样香槟葡萄香型\n需要推荐or修改3~5款唇部用食品级香型\n需求价格：500以内\n目前客户暂时无出口需求\n需求时间：7.24', 'Eios--香槟葡桃唇部用修改20260720', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2079399211807248386', '0', '0', '17253690046572896', '周宇', '2026-07-21 10:53:00', '113845370124130976', '彭佳庆', '2026-07-30 09:40:47', '1', '2079399212088229889', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260721-0005', '2079110741012500482', '芬寸--翡翠青柚、伊塔克香水油调整20260720', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '1000以内', '113845370124130976,16466317325076496', NULL, '2037362401694695425', 'Peggie', 'Peggie\n18779270160\n上海市黄浦区SOHO复兴广场B座607 Peggie 18779270160\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP2327CLY -- IFRA 5A 15%', 'LYP2327CLY-翡翠青柚3（香水）\nLYP2322CLY-永恒之乡伊塔克3（香水）\nLYP2322DLY-永恒之乡伊塔克4（香水）', '74100603681630', '2026-07-30 00:00:00', NULL, NULL, '彭佳庆,梁皓', '寄：Peggie\n客户目前对该两款香型需要应用于香水油内\n\n01/ 翡翠青柚LYC2327BLY\n需求保留原本香气内的果肉多汁感增加果皮的涩感\n需要突出香气的层次感\n\n02/ LYC2322BLY 伊塔克\n需要两个方向修改\n\n方向1：\n增强目前版本内的青花椒感做  辛香浆果  方向调整！！！\n\n方向2：\n增强目前版本内的青花椒感做  草本木质  方向调整！！！\n\n\n客户香水油最大添加量35%需注意法规\n需求价格：1000以内\n需求时间：最晚7.31寄出', '芬寸--翡翠青柚、伊塔克香水油调整20260720', '1', '无', NULL, NULL, NULL);
