INSERT INTO `w_bo_gd_20250707155940` VALUES ('2080590863976599553', '0', '0', '17253690046572896', '周宇', '2026-07-24 17:48:12', '113845370124130976', '彭佳庆', '2026-07-30 15:50:40', '1', '2080590864257581057', 'RUNNING', '运行中', '909783222', '评香部', '13', 'YPGD-20260724-0028', '2080524058666962945', '清清美家居-线下选香推荐', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2026-11-07 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '暂无', '113845370124130976,050363634136321790', NULL, '2056926824092360705', '徐先生', '徐先生\n13065721278\n浙江省杭州市拱墅区远洋国际中心B座901室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '07/30 SH补寄样 -- DH-Y251252	肌肤之水\n------\nLYP790ALY	慵懒周末  <库存替换>\nLYP1187BLY	水之恋  <配方号更新>', NULL, '74100603681635', '2026-07-30 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '根据客户线下选香进行递样，目前仅为香气确认阶段后续客户反馈会继续更新需求\n产品用于香水、家居香氛、个护、香氛玩偶\n寄：浙江省杭州市拱墅区远洋国际中心 B 座 901 室，徐先生收，13065721278\n时间：7-27前\n寄样：5g香精\n价格需求：暂无\nLJP2468BLJ	紫罗兰30\nLJP2013ALJ	追光夜莺\nLYP1187BLY	水之恋\nLYP1500BLY	肌肤之水\nLYP2175BLY	自己\nJKP2448BJK	都灵21\nLYP2281BLY	茶瀑\nLYP2176BLY	雷暴\nLYP790CLY	慵懒周末\nLJP2319CLJ	迪拜巧克力\nLCP2100ALC	美味棉花糖81\nLYR1273ALY	绿豆沙', '清清美家居-线下选香推荐', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2081563066704564225', '0', '0', '17253690046572896', '周宇', '2026-07-27 10:11:23', '113845370124130976', '彭佳庆', '2026-07-29 14:09:15', '1', '2081563067019100162', 'RUNNING', '运行中', '909783222', '评香部', '9', 'YPGD-20260727-0001', '2079861597169225729', '粉合--城市植萃系列推荐20260722', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '350以内', '113845370124130976,16466317325076496', NULL, '2056975729211432961', 'Gary', 'Gary\n13701974151\n上海市长宁区愚园路锦园805弄15号 Gary13701974151\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '睡眠：LYP932DLY -- 薰衣草\n焦虑：LYP1644BLY -- 薄荷、柠檬\n代谢：LYP2012BLY -- 生姜\n抑郁1：LYP2014CLY -- 罗勒、柠檬 \n抑郁2：SYP522BSY -- 天竺葵  香根草\n\n', NULL, '销售送样	', '2026-07-29 00:00:00', NULL, NULL, '彭佳庆,梁皓', '销售自提\n需要推荐4款大牌大牌香氛\n需要香精内部添加的天然精油有治疗失眠、焦虑、肥胖等城市病需求的功效\n不用我们做任何宣传只需要内部加了类似功效的天然原料即可\n客户以次为卖点，只需每款有一个原料即可，需要四个不同的天然精油\n都市病：睡眠障碍、情绪焦躁、肥胖、抑郁等\n睡眠障碍：薰衣草、洋甘菊、岩兰草、佛手柑和檀香\n情绪焦躁：薰衣草\n促进代谢：薄荷、姜\n抑郁：玫瑰、香根草、依兰、薰衣草、佛手柑、罗勒、柠檬、乳香、洋甘菊、广藿香、鼠尾草、茉莉、薄荷、缬草根和天竺葵\n如有其他选择也可使用但需告知针对的都市病以及使用精油\n需求价格：350以内\n从上海库选样\n需求时间：7.29\n需要10%香水加香产品', '粉合--城市植萃系列推荐20260722', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2081563560617414658', '0', '0', '17253690046572896', '周宇', '2026-07-27 10:13:21', '17201757871959617', '寄样员', '2026-07-28 10:56:34', '1', '2081563560831287298', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260727-0002', '2081549576942096386', '逐本卸妆膏新品开发-舒彩（重要）', NULL, '1', '需求明确', '1', '客户新品开发', '204', '面部清洁', '2026-07-28 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400', '113845370124130976,050363634136321790', NULL, '2064892343747596290', '李玲', '李玲\n17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5150605283572', NULL, NULL, NULL, '彭佳庆,逯柏松', '香味三个方向:\n1.茉莉花茶香方向，对标茉莉花茶大牌同款香调，已经得到了大众认可，且有国民接受度。参考阿玛尼和风茉莉  or  cucci花悦(清新甜润花香)，也可以提案。\n2.果香+茶香方向:试一下青少年洁面的果茶香加入卸妆膏好不好闻，做个内测。\n3.纯净的绿茶香方向:(最好可以找到好闻的大牌香水作为对标，发给供应商模仿。)参考阿玛尼玉龙茶香，也可以提案。\n以上三个香味方向可以让供应商提案做推荐。\n价格：400以内\n应用：卸妆膏\n香精：15ml\n备注，每个香型方向推荐2-3款\n时间：最好今天寄出，最晚明天寄出7/28\n寄件地址：李玲', '逐本卸妆膏新品开发-舒彩（重要）', '1', '无', NULL, NULL, NULL);
