INSERT INTO `w_bo_gd_20250707155940` VALUES ('2081588402355933186', '0', '0', '17253690046572896', '周宇', '2026-07-27 11:52:04', '113845370124130976', '彭佳庆', '2026-07-27 16:57:27', '1', '2081588402611748865', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260727-0025', '2080538432613879810', '跑红集团   精华乳和泥膜香精推荐（加急项目）', NULL, '1', '需求明确', '1', '客户新品开发', '205', '面部护肤', '2027-07-24 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '500元', '1638968357988946', NULL, '2080529302616510466', '薛曦曦', '薛曦曦\n17318832225\n浙江省杭州市滨江区华业发展中心41楼跑红集团\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '【精华乳-对香】\n标样--香奈儿1号 红山茶面霜', NULL, 'SF1574204101684', '2026-07-27 00:00:00', NULL, NULL, '何家文', '时间：项目非常急，客户要在7月28日周二能收到样品后，立马和老板内部选香，确定项目。所以麻烦周一收到样品后，帮忙加急选香寄出，谢谢\n\n样品：客户安排两款产品精华乳和泥膜base各30g，以及新的香精方向（奇华顿香精）。7月24日周五寄出样品，请留意查收。\n背景：上次给客户寄的样品LYP1444ALY、SYB1235ASY、SYP587FSY、LYP1560BLY和SYB2111CSY用在精华液中，受测者反馈结果不太理想，反馈主要是觉得有草木味和洗衣粉味的味道，让产品整体没有了高级感。\n需求一：客户提供的奇华顿香精，客户对这款香的气味是认可的，但遮盖不住泥膜基料的气味，所以希望我们能按照这款香精的气味方向推荐类似的香型，同时要能遮盖住泥膜base的气味；\n产品：泥膜（添加量：0.15%-0.2%）；\n价格：500元\n\n需求二：客户寄来的两款精华乳，请帮忙对香，推荐跟样品气味类似的香型或者跟样品香气风格类似的也可以；\n产品：精华液和精华乳；\n价格：500元\n\n两个需求的收件地址：浙江省杭州市滨江区华业发展中心41楼跑红集团  薛曦曦17318832225', '跑红集团 精华乳和泥膜香精推荐 (加急)_260727', '1', '无', NULL, NULL, NULL);
