INSERT INTO `w_bo_gd_20250707155940` VALUES ('2081921100698062850', '0', '0', '16455177663846080', '常晓爽', '2026-07-28 09:54:05', '17201757871959617', '寄样员', '2026-08-05 14:19:13', '1', '2081921101016793090', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260728-0005', '2079120450075480066', '自然风物系列开发-西苔（重要）', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2026-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300', '113845370124130976,050363634136321790', NULL, '2059907565130571778', 'Bella', 'Bella\n15257009611\n浙江省杭州市萧山区盈丰街道永晖路233号杭州湾智慧谷10楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1224124362945', NULL, NULL, NULL, '彭佳庆,逯柏松', '【DXA2454ADX 乌樟】溶剂：二丙二醇甲醚乙酸酯，样品：50g\n自然风物系列\n中国特色植物或者产物，有中国地域产物特点，花/果/茶/叶/根都可以；需要配合市场数据，什么方向是认可度比较高的，进行开发。\n结合市场推荐香型。\n价格：300以内\n应用：无火（异构）\n香精：10ml\n备注：需要加香产品（加香量10%）客供base\n寄样地址：bella', '西苔藤条推荐', '2', '加香', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2081931659040493570', '0', '0', '16455177663846080', '常晓爽', '2026-07-28 10:36:03', '17201757871959617', '寄样员', '2026-07-28 11:35:24', '1', '2081931659338252289', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260728-0007', '2076840923106365442', '美创本源  护肤香精调配', NULL, '1', '需求明确', '5', '香精库推荐', '205', '面部护肤', '2027-07-14 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300-500元之间', '1638968357988946', NULL, '2074664413750611969', '林丽', '林丽\n13715045975\n地址：广州市从化区太平镇新兴路398号6栋，广州市仙迪生物（上坡保安室）\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1223043383545', NULL, NULL, NULL, '何家文', '客户给到的三调方向，可以做参考。可以直接在我们现有的油样库推荐，不用特调。\n前调：淡佛手柑、小豆蔻、粉红胡椒、迷迭香\n中调：零陵香豆、柔和琥珀\n后调：·檀香、香根草、愈创木、雪松\n基底是这款香的核心重点。涂抹在皮肤上需留香数小时，干香后质感愈发细腻高级。\n同时客户不要浓郁花香、果香调、糖果甜腻感、强烈水生清新调和厚重柑橘味\n产品：护肤品\n价格：300-500元之间\n地址：仙迪林丽收', '美创本源护肤香精', '1', '无', NULL, NULL, NULL);
