INSERT INTO `w_bo_gd_20250707155940` VALUES ('2085186641911074817', '0', '0', '16455177663846080', '常晓爽', '2026-08-06 10:10:11', '17201757871959617', '寄样员', '2026-08-06 16:28:37', '1', '2085186642171027458', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260806-0005', '2084090625182912513', '浅香-适配沐浴露配方-20260803', NULL, '1', '需求明确', '5', '香精库推荐', '2021', '沐浴露', '2027-08-03 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150元/KG。', '17400514601408872,1638968357988946', NULL, '2062705935016472578', '陈银娜', '陈银娜\n13710822247\n广东广州市白云区鹤龙街道黄边愿景中心21楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1225133627144', NULL, NULL, NULL, '于姗姗,何家文', '新项目需要以下两款产品的同款香精，适配沐浴露配方。\n①多芬深层营润滋养美肤沐浴乳 \n②多芬樱花甜香滋养美肤沐浴乳\n核心需求：\n陈银娜\n1. 气味尽量还原原版，稳定性过关，不与原料冲突。', '浅香推荐', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2085190029839159297', '0', '0', '17253690046572896', '周宇', '2026-08-06 10:23:39', '113845370124130976', '彭佳庆', '2026-08-06 16:33:32', '1', '2085190030187192321', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260806-0006', '2056242808708096001', '培蘑--百香果创香20260518', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000以内', '113845370124130976,16466317325076496', NULL, '2056240351974219777', '冷先生', '冷先生\n17717022237\n上海慈竹路608弄3号楼1005 冷先生 17717022237\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '74100603681646', '2026-08-06 00:00:00', NULL, NULL, '彭佳庆,梁皓', '冷先生项目\nSYP2043DSY 百香果香基\n调香师：刘扬\n1.加入多汁、精纯的果香状态。\n百香果香基未经稀释的状态是最好的，果香饱满，目前果香的状态比较偏平，经过多轮普通消费者测试，大家反馈平平。增\n加多汁意向可在前调迅速抓住鼻子。\n2.降糖\n百香果被Pape Moe定位为热卖选题（同草莓、芭乐）为了更好的销量希望适当降低甜度，去适配更多的中国消费者。\n3.多样的搭配增加耐闻度，与市面上单一果香品牌拉开距离\n我们提出一些搭配思路供调香师参考\nA.焚香+百香果\n轻盈的日式焚香与百香果的热情碰撞\nB.草本+百香果\n罗勒、尤加利、薄荷、斑斓一些比较受欢迎的草本都可以尝试。\nC.辛香+百香果\n一些比较芳香偏绿的辛香，芫荽、黑胡椒、小豆蔻、月桂叶等等\n\n需要根据客户需求提供3个方向递样\nSYP2043DSY 百香果香基整体减低甜感，增加热带果感\n该项目指定调香师：刘扬\n1、焚香+百香果\n2、草本+百香果\n3、辛香+百香果\n\n需求价格：2000以内\n需要 20%香水加香产品\n需求时间：6.5寄出', '培蘑--百香果创香20260518', '1', '无', NULL, '', '');
