INSERT INTO `w_bo_gd_20250707155940` VALUES ('2087359181576196098', '0', '0', '17253690046572896', '周宇', '2026-08-12 10:03:05', '17201757871959617', '寄样员', '2026-08-18 17:40:10', '1', '2087359181840343042', 'RUNNING', '运行中', '909783222', '评香部', '10', 'YPGD-20260812-0004', '2084856782135480322', '弗止--阴阳师ip联名家居香氛推荐20260805', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200~300', '16466317325076496,113845370124130976', NULL, '2055159748134658049', 'jiojio', 'jiojio\n15178065377\n上海市静安区江场路1447号云芯科创中心T1号楼19楼DO事业部 jiojio，15178065377\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5119782708546', NULL, NULL, NULL, '梁皓,彭佳庆', '寄：jiojio\n根据客户5位角色需求推荐角色香\n需要每位角色推荐2支\n由于该客户品类用于香薰类故需要优化香气表现力：香气强度与扩香能力\n客户市场参照样如无仿香可提供类似香气感受的大牌香氛\n寄出前请确认加香产品强度与香气表现\n\n1、帝释天\n前调：香柠檬、杜松子、醛香\n中调：薰衣草、小豆蔻、小苍兰/莲花/忍冬\n后调： 雪松、琥珀、白麝香\n对标大牌香氛：艾克卡帕-白苔、古特尔-忍冬\n销售推荐：紫罗兰30\n\n2、阿修罗\n前调： 苦艾、生姜、藏红花\n中调： 黑胡椒、没药、焚香\n后调： 广藿、麝香/皮革、沉香\n对标大牌香氛：解放橘郡-情水（龙与玫瑰）、TF-隐秘没药\n\n3、酒吞童子\n前调：柚子、花椒、小豆蔻\n中调：酒香元素、烟草、李子\n后调： 橡木、皮革、劳丹脂\n对标大牌香氛：Byredo-最后一刻，帝国之香-俄罗斯琥珀\n销售推荐：单一麦芽、巴塔哥尼（草原落鲸）\n\n4、茨木童子\n前调： 柑橘、青椒、灰烬/火药\n中调： 玫瑰、肉桂、公丁香\n后调： 冷杉、乳香、雪松\n对标大牌香氛：川久保玲-惊艳绿、4711-原始森林古龙\n销售推荐：近期做过的香樟木\n\n5、鬼切\n前调：金属、臭氧、血橙\n中调：鸢尾根、黑胡椒、茶叶\n后调：橡木苔、白麝香、广藿\n对标大牌香氛：潘海利根-裁缝、帝门特-暴风雨\n\n需求价格：200~300元\n需要10%无火加香产品50g，香精3g左右感受一下即可\n需求时间：8.19前寄出', '弗止--阴阳师ip联名家居香氛推荐20260805', '2', '加香', NULL, '', '');
