INSERT INTO `w_bo_gd_20250707155940` VALUES ('2087476198899699713', '0', '0', '17253690046572896', '周宇', '2026-08-12 17:48:04', '17201757871959617', '寄样员', '2026-08-17 17:12:47', '1', '2087476199264509953', 'RUNNING', '运行中', '909783222', '评香部', '7', 'YPGD-20260812-0027', '2086725202825170945', '上海筷予--东南亚文旅香型推荐20260810', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200左右', '16466317325076496,113845370124130976', NULL, '2086721893083107329', '刘', '刘\n18079791767\n上海市长宁区江苏路，722弄4栋603 刘18079791767\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '74100603681554', '2026-08-13 00:00:00', NULL, NULL, '梁皓,彭佳庆', '根据客户需求结合地方特色+文旅，对以下4个主题进行香型推荐\n1. 光与盐  --  海洋/清新/清爽   ----   但是不要太强的水生调，以清新干净冷感为主\n2. 南洋旧梦 --  草本/药香/清透  ----  斑斓叶的味道，可以带一点糯米，有药感的斑斓香\n3. 骑楼老宅 -- 木质/冷暖交织 ---- 有一种老宅子+老书籍的味道，但是要带一点暖或者冷的热带感\n4. 深白月夜 -- 白花/清冷/干净 ---- 鸡蛋花的味道，但是不要太直给。还是要偏一点冷感\n可在大牌香氛内寻找适合的推荐\n产品用于蜡烛+香氛喷雾，后续会用于车载\n每款出题需要推荐2~3支\n需要10%香水加香产品\n需求价格：200左右\n需求时间：8.13', '筷予--东南亚文旅香型推荐20260810', '2', '加香', NULL, '', '');
