INSERT INTO `w_bo_gd_20250707155940` VALUES ('2088074887196299265', '0', '0', '17253690046572896', '周宇', '2026-08-14 09:27:02', '113845370124130976', '彭佳庆', '2026-08-19 14:08:04', '1', '2088074887452057601', 'RUNNING', '运行中', '909783222', '评香部', '10', 'YPGD-20260814-0001', '2087469823150772225', '香型推荐-赤翎川月', NULL, '1', '需求明确', '1', '客户新品开发', '3011', '香水', '2026-09-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000', '050363634136321790', NULL, '2087468994553434114', '柳兰若', '柳兰若\n13701266645\n中国上海市虹口区东长治路505号雷士德工学院旧址，放快递室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP1069ALY  泥煤1（原版）  IFRA 4类，10%\n---\nLYP735ALY 历史一刻 -- 配方更新\nLYP736ALY 凝固时光 -- 水质已改好', 'LYP2485ALY-历史一刻2（香水）', '74100603681558', '2026-08-19 00:00:00', NULL, NULL, '逯柏松', '1. 金钱的味道【油质】：海水味道，混合金属和纸张---金钱演化的历史\n\n2. 权力的游戏【油质】：印泥的味道【像是印玺要盖章】，木质焚香的祭祀感觉，以及粮食的味道。\n\n----国家之道，在祀与戎---祭祀和战争的感觉。\n\n-----粮食是因为国家的感觉是社稷，社稷就是粮食\n\n3. 天赋的传承【水质】：书卷气，墨水，图书馆的味道，茶和咖啡味道，学院派，大学里面的味道\n\n有寒窗苦读的感觉。\n\n4. 名望的中心【水质】：胶卷的味道，镁光灯的闪烁灼烧味道，还有觥筹交错的一点点红酒香。\n\n价格：2000\n应用：香水\n香精：10ml\n时间：8月21号寄出', '香型推荐-赤翎川月_260814', '1', '无', NULL, '', '');
