INSERT INTO `w_bo_gd_20250707155940` VALUES ('2089166342237179905', '0', '0', '16455177663846080', '常晓爽', '2026-08-17 09:44:05', '17201757871959617', '寄样员', '2026-08-18 17:26:01', '1', '2089166342476161026', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260817-0003', '2085305490958438401', '杭州云韵--松气--碧螺春、听雨、香水柠檬家居香氛新品推荐', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '16466317325076496,113845370124130976', NULL, '2085295280546107394', 'Gia', 'Gia\n15058351217\n浙江省杭州市余杭区仓前街道创景路奥克斯时代未来之城5幢3001 Gia 15058351217\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5112383081990', NULL, NULL, NULL, '梁皓,彭佳庆', 'LJB2028ALJ加点气泡感果汁感\n根据客户需求进行推荐递样\n需求1：西湖龙井\n同步可推荐茉莉花茶与单枞茶香推荐\n香气描述：主调有明显的西湖龙井茶香，最好是可以有点西湖龙井的特色豆香。感觉上比较淡雅，让人置身于茶室或者是置身于雨后茶园的感觉。\n\n需求2：香水柠檬\n根据已有香水柠檬Acord进行递样\n\n需求3：听雨\n根据客户描述推荐苔藓、壤香推荐，需要有国风感\n香气描述：闻起来让人想到晨露、雨天森林、雪松、山林微风、橡木苔。感觉很适配天青色，最好不要太过偏向于水生调\n\n产品首先应用于车载、香包、香氛喷雾\n后续品类拓展会应用于蜡烛无火以及个护产品内\n需要考虑产品的适配性与通用性\n需求价格：300以内\n需求时间：8.10上海办需要收到第一批推荐样品的香气确认', '松气', '1', '无', '8.10评香会带样品至上海办，后续销售安排寄出', '', '');
