INSERT INTO `w_bo_gd_20250707155940` VALUES ('2089191887012352001', '0', '0', '17253690046572896', '周宇', '2026-08-17 11:25:36', '113845370124130976', '彭佳庆', '2026-08-19 14:15:52', '1', '2089191887234555906', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260817-0014', '2089173058077052930', '蓝调睡意推荐-宋朝', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2026-09-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '250', '050363634136321790', NULL, '2069339637448429569', '马女士', '马女士\n15988856039\n杭州市滨江区长河街道塘子堰路159号笨鸟园区D幢6楼马女士15988856039\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '枕头贴纸 助眠精油，2款，舒缓放松、必须含有薰衣草精油；\n可一款偏 精油疗愈，一款偏 花香舒缓；', 'LYA2484ALY-薰衣草1（香片）', '74100603681559', '2024-08-19 00:00:00', NULL, NULL, '逯柏松', '香味：薰衣草  \n三调参考：(蓝调睡意BLUE-TINTED SLUMBERTOP佛手柑、柑橘叶MIDDLE煎衣草、甜马郁兰、洋甘菊BOTToM白麝香、零陵香豆、檀香\n天然精油：董衣草油、香叶天竺葵油、岩兰草根油、玫瑰花油、蓝桉叶油、檀香油、五味子油、乳香油、麦卢卡精油。\n（可以部分添加精油，薰衣草油必须要含）\n推荐两款\n价格：250以内\n香精：15ml\n应用；香卡\n时间：8月19前寄出', '蓝调睡意推荐-宋朝_20260817', '1', '无', NULL, '', '');
