INSERT INTO `w_bo_gd_20250707155940` VALUES ('2091781477774643201', '0', '0', '16275212368889684', '赵文雅', '2026-08-24 14:55:42', '17201757871959617', '寄样员', '2026-08-24 15:34:10', '1', '2091781478051373058', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260824-0030', '2090625607787335682', '森熹堂-推荐高端香氛-0821', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-08-21 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '邢芬,郭治爽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '16855125875633810,04476151371724', NULL, '2090624826409472002', '紀善傑', '紀善傑\n+886 0905 095 538\n台灣 台北市士林區士商路12號4樓\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5156139835668', NULL, NULL, NULL, '邢芬,郭治爽', '给他选高端的，从库里选就行，先选一轮香（台湾客户）\n\n我们目前正在开发一组 高端肌肤护理、洗护及空间香氛产品，想了现有香精中，有没有比较适合我们整体定位的香型。\n\n我们希望整体香气走 高端极简、静奢、自然材质感、建筑空间感 的路线，香气需要克制、干净、有层次，不希望太甜、太浓艳，也希望避免明显的传统日化感、洗衣液感或常见酒店香氛感。\n\n目前比较喜欢几个方向：\n\n1. 檜木／雪松／苦橙叶／岩兰草\n    偏冷感、干净、现代的木质调。\n2. 白茶／苦橙叶／檜木\n    清透、微苦、有空气感，不要明显甜茶感。\n3. 黑茶／无花果叶／干木质\n    成熟、安静、有植物茎叶感，无花果不要偏甜果肉。\n4. 紫苏／冷石／矿物／木质\n    希望呈现雨后石材、植物叶片、冷空气及建筑空间感，这个方向我们比较重视。\n5. 低调鸢尾／木质／柔和麝香\n    偏贴肤、干净、低粉感，不要传统化妆品或口红感。\n\n主要应用会包含 洗发产品、护手霜、空间喷雾、藤条扩香及香氛蜡烛。\n\n第一阶段希望先从贵司现有成熟香型里面筛选，不急着做完全定制。您可以先根据以上方向，帮我推荐几款比较符合这种调性的香精，我们先拿样评估。\n\n我们比较重视 香气品质、层次感及辨识度，价格可以先从中高端到高端系列推荐。', '推荐', '1', '无', NULL, '', '');
